'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('not any','A transparent negative phrase combining not with any; it denies the existence of even one item in the relevant group.',C('not any.s1','否定数量','There is not any clean water left in the storage tank, so the crew must use the reserve supply.','储水罐里一点干净水也不剩，因此工作人员必须使用备用水源。','There is not any clean water left / in the storage tank / so the crew must use the reserve supply.','not any 放在不可数名词前，表示完全没有。','水已用尽，后文说明需要备用水。'),M('There are any seats left in the hall, so the late guests have nowhere to sit.','There are not any seats left in the hall, so the late guests have nowhere to sit.','句意要求“一个座位也没有”，但原句缺少否定词 not。','grammar'),[q('What is left in the storage tank?','no clean water','a large supply of clean water','several clean towels','句子明确说储水罐里没有干净水。'),q('Which sentence denies that even one ticket remains?','There are not any tickets left.','There are any tickets left.','There are some tickets left.','not any 与复数名词连用，表示一张也不剩。',1,'grammar'),q('What must the crew use after the tank runs out?','the reserve supply','the empty tank','a ticket office','后半句说明工作人员要改用备用水源。',1,'context'),q('In “not any clean water,” any refers to?','an amount that is completely absent','a particular tank that is full','a tool used to repair pipes','any 在否定结构中表示完全没有该物。',1,'meaning')]);
P('not anywhere','Formed from not and anywhere, this phrase means in no place and normally appears with a negative verb.',C('not anywhere.s1','任何地方都不','The missing field notebook was not anywhere in the tent, so the researcher checked the supply hut next.','丢失的野外笔记本不在帐篷的任何地方，因此研究人员接着检查储物棚。','The missing field notebook was not anywhere / in the tent / so the researcher checked the supply hut next.','not anywhere 常与 be 动词连用，表示某物不在任何地点。','帐篷里找不到后，研究人员转去别处寻找。'),M('The guide did not find the compass not anywhere in the pack.','The guide did not find the compass anywhere in the pack.','否定动词后再加 not anywhere 构成不必要的双重否定；用 anywhere 即可。','grammar'),[q('Where was the field notebook?','It was in no place inside the tent.','It was under the sleeping bag in the tent.','It was at the supply hut already.','not anywhere in the tent 表示帐篷里任何地方都没有。'),q('Which sentence uses “not anywhere” correctly?','The key is not anywhere in this drawer.','The key is not anywhere found in this drawer.','The key is anywhere not in this drawer.','否定 be 动词后可接 not anywhere，再用地点短语说明范围。',1,'grammar'),q('What did the researcher check next?','the supply hut','the notebook cover','the compass needle','找到帐篷里没有笔记本后，研究人员检查储物棚。',1,'context'),q('“Not anywhere” is closest in meaning to?','in no place','at every location','in a nearby place','该短语表示“任何地方都不”。',1,'meaning')]);
P('not deep','A transparent combination of not and deep, used to say that a place or object does not extend far down from its surface.',C('not deep.s1','深度不足','The stream is not deep near the footbridge, allowing children to cross only under an adult’s supervision.','人行桥附近的溪水不深，但孩子们仍只能在成人看护下通过。','The stream is not deep / near the footbridge / allowing children to cross only under an adult’s supervision.','not deep 是 be 动词加形容词的否定结构，表示深度不足。','水浅描述深度，但不自动意味着安全，句子保留看护要求。'),M('The pool is not deep as the lake beside it.','The pool is not as deep as the lake beside it.','比较级结构应为 not as + 形容词 + as，原句漏掉第一个 as。','grammar'),[q('How deep is the stream near the bridge?','It does not extend far down.','It is too deep to see the bottom.','It is completely dry.','句子直接说明桥边溪水不深。'),q('Which comparison is grammatical?','This pond is not as deep as the reservoir.','This pond is not deep than the reservoir.','This pond is not so deeper the reservoir.','not as deep as 是表达“不如……深”的正确结构。',1,'grammar'),q('When may children cross the stream?','only with an adult supervising','alone whenever they wish','only after the stream dries up','虽然水浅，句子仍明确要求成人看护。',1,'context'),q('“Not deep” describes a lack of?','downward distance from the surface','width from bank to bank','water movement along a channel','deep 在此指从表面向下的深度。',1,'meaning')]);
P('not either','A negative phrase using not with either; as a response or clause-final addition, it means also not.',C('not either.s1','否定中的“也不”','Mina does not drink coffee, and her brother does not either; both choose herbal tea.','米娜不喝咖啡，她哥哥也不喝；两人都选花草茶。','Mina does not drink coffee / and her brother does not either / both choose herbal tea.','either 可放在否定句末表示“也不”，常与 not 连用。','第二句补充哥哥同样不喝咖啡。'),M('Mina does not drink coffee, and her brother does not too.','Mina does not drink coffee, and her brother does not either.','否定分句末表示“也不”用 either，不用 too。','word-choice'),[q('What do Mina and her brother both avoid?','coffee','herbal tea','all drinks','两人都不喝咖啡。'),q('Which reply correctly means “I also do not”?','I do not either.','I do not too.','I either do.','否定句末的“也不”通常用 either。',1,'grammar'),q('What do the siblings choose instead?','herbal tea','coffee with milk','plain water only','句子说两人都选择花草茶。',1,'context'),q('In the example, either adds which idea?','the brother shares Mina’s negative choice','the brother drinks coffee more often','Mina changes her mind','either 表示哥哥也作出相同的否定选择。',1,'meaning')]);
P('not ever','A combination of not and ever that emphatically means never at any time; the two words are also used in questions and conditional contexts.',C('not ever.s1','任何时候都不','The archivist promised not ever to remove the original map from its climate-controlled case.','档案管理员承诺绝不会把原始地图从恒温展柜中取出。','The archivist promised / not ever to remove the original map / from its climate-controlled case.','not ever 常用于强调“绝不、任何时候都不”，ever 修饰动词 remove。','承诺强调在任何时候都不取出原图。'),M('The archivist has not never removed the map from its case.','The archivist has not ever removed the map from its case.','not never 叠加两个否定；改为 not ever 保留“从未”的意思。','grammar'),[q('What did the archivist promise not to do?','remove the original map from its case','replace the climate controls','make a copy for the visitors','承诺不把原始地图取出展柜。'),q('Which phrase gives emphatic negative meaning?','not ever','ever since','not yet again','not ever 表示任何时候都不。',1,'meaning'),q('Where is the map kept?','in a climate-controlled case','in a visitor’s notebook','under the archive desk','句子说明地图放在恒温展柜里。',1,'context'),q('What is wrong with “has not never removed”?','It contains two negatives for the intended single denial.','It uses a past participle after has.','It incorrectly names a type of map.','完成时可用 has removed；错误在 not never 的双重否定。',1,'grammar')]);
P('not much','Not much is formed from not plus the quantifier much and means not a large amount, especially with uncountable nouns.',C('not much.s1','数量不多','There is not much fuel in the generator, so the night team will switch it off after the final test.','发电机里的燃料不多，因此夜班人员会在最后一次测试后关机。','There is not much fuel / in the generator / so the night team will switch it off after the final test.','much 修饰不可数名词 fuel，not much 表示数量不多。','燃料所剩不多，团队安排最后测试后关机。'),M('There are not much fuel in the generator for the final test.','There is not much fuel in the generator for the final test.','fuel 在此不可数，there be 结构应使用 is。','countability'),[q('What is scarce in the generator?','fuel','spare notebooks','night workers','句子说发电机燃料不多。'),q('Which noun fits “not much” here?','fuel','batteries','generators','fuel 在此不可数，搭配 not much。',1,'countability'),q('When will the night team switch off the generator?','after the final test','before filling it with fuel','at the start of the night','所剩燃料要留给最后一次测试，之后关机。',1,'context'),q('“Not much fuel” means?','a small amount of fuel','many separate fuel containers','no generator at all','not much 表示数量不大，不等于没有发电机。',1,'meaning')]);
P('not really','Not really combines not with really to mean not quite or not to a great degree, and it can also soften a disagreement.',C('not really.s1','不太；不完全是','When asked whether the new sensor solved every problem, the engineer replied, “Not really; it still misses faint signals.”','有人问新传感器是否解决了所有问题，工程师回答：“不完全是；它仍会漏掉微弱信号。”','When asked whether the new sensor solved every problem / the engineer replied, “Not really” / it still misses faint signals.','Not really 可作简短回答，委婉表示“不完全是”。','传感器仍会漏检，因此并未完全解决问题。'),M('She not really understands why the sensor missed the faint signal.','She does not really understand why the sensor missed the faint signal.','一般现在时实义动词 understand 的否定形式需要 does not。','grammar'),[q('Did the sensor solve every problem?','No, not completely.','Yes, it detects every faint signal.','It was never tested.','工程师回答 not really，并指出仍会漏掉信号。'),q('Which sentence has the correct verb structure?','He does not really trust the first reading.','He not really trusts the first reading.','He does not trusts the first reading.','does not 后接动词原形 trust。',1,'grammar'),q('What weakness remains?','faint signals may be missed','the sensor cannot be switched on','the engineer lost the manual','传感器仍漏掉微弱信号。',1,'context'),q('As a reply, “Not really” most nearly means?','not quite','absolutely yes','not at any location','它委婉表示“不完全是”，不是完全肯定。',1,'meaning')]);
P('not so','Not so combines not with so to mean not to that degree; it can also introduce a correction, as in “not so fast.”',C('not so.s1','程度没有那么……','The northern slope is not so steep after the trail turns east, making the last section easier to climb.','步道转向东侧后，北坡就没有那么陡，最后一段更容易攀登。','The northern slope is not so steep / after the trail turns east / making the last section easier to climb.','not so + 形容词表示程度没有那么高。','步道转向后坡度下降，因此攀登更容易。'),M('The northern slope is not so much steep after the trail turns east.','The northern slope is not so steep after the trail turns east.','so 直接修饰形容词 steep，不需要 much。','grammar'),[q('How does the slope change after the trail turns east?','It is less steep.','It becomes much steeper.','It disappears completely.','not so steep 表示没有那么陡。'),q('Which phrase is standard?','not so steep','not so much steep','not so steeply slope','so 在此直接修饰形容词 steep。',1,'grammar'),q('Which section becomes easier to climb?','the final section','the trail’s western entrance','a route that has no slope','句子说最后一段变得容易攀登。',1,'context'),q('“Not so” points to a degree that is?','lower than the one being discussed','exactly equal to every possible degree','located in no place','not so 用来否定或降低前述程度。',1,'meaning')]);
P('notable','Notable comes through French from Latin notabilis, “worthy of note,” from notare, “to mark”; it means important, interesting, or easy to notice.',C('notable.s1','值得注意的','The report recorded a notable drop in river pollution after factories installed the new filters.','报告记录到工厂安装新过滤器后河流污染显著下降。','The report recorded a notable drop / in river pollution / after factories installed the new filters.','notable 作形容词修饰 drop，表示变化显著、值得注意。','过滤器安装后污染下降，报告特别记录这一变化。'),M('The survey called the change notable because no one could detect it and it had no measurable effect.','The survey called the measurable change notable because it was easy to detect.','完全无法察觉且没有影响的变化不能据此称为显著。','meaning'),[q('What change did the report record?','a significant reduction in river pollution','a rise in the number of factories','a change in the river’s name','report 记录的是污染下降。'),q('Which event is most likely notable?','a clearly measurable fall in pollution','an unrecorded change too small to detect','a routine step with no effect','notable 指重要、显著或容易引起注意的事。',1,'meaning'),q('What helped produce the pollution drop?','factories installed new filters','the report changed its format','the river was renamed','句子将过滤器安装与污染下降联系起来。',1,'context'),q('The Latin source idea in notable is closest to?','worthy of being marked or noticed','able to float on water','a small paper book','词源中的 notabilis 有“值得记下、标记”之意。',1,'word-formation')]);
P('notably','Notably is formed from notable plus -ly; it means in a noticeable way or, before an example, particularly.',C('notably.s1','显著地；尤其','Several wetlands recovered after the cleanup, notably the marsh beside the old railway bridge.','清理后有几处湿地恢复了生机，尤其是旧铁路桥旁的沼泽。','Several wetlands recovered after the cleanup / notably the marsh / beside the old railway bridge.','notably 可引出特别值得注意的具体例子。','后半句特别指出恢复明显的那片沼泽。'),M('Several wetlands recovered, notable the marsh beside the railway bridge.','Several wetlands recovered, notably the marsh beside the railway bridge.','此处需要副词 notably 引出特别突出的例子，不能用形容词 notable。','word form'),[q('Which wetland is singled out?','the marsh beside the old railway bridge','every pond in the city','the field beside the station','notably 后指出旧铁路桥旁的沼泽。'),q('Which sentence uses the adverb correctly?','The species notably increased after the marsh was restored.','The species notable increased after the marsh was restored.','The notably species increased after the marsh was restored.','notably 是副词，可修饰 increased。',1,'word form'),q('What happened after the cleanup?','several wetlands recovered','the railway bridge was removed','all marshes became dry','句子开头说明几处湿地恢复。',1,'context'),q('Before a named example, notably means?','particularly or especially','in a hidden place','at a lower price','这里 notably 用来特别指出一个例子。',1,'meaning')]);
P('notary','Notary comes from Latin notarius, “secretary or shorthand writer,” from nota, “mark”; a notary authenticates documents or administers oaths.',C('notary.s1','公证人','A notary verified the signatures on the property papers before the buyer submitted them to the land office.','买方把房产文件提交土地登记处前，公证人核验了文件上的签名。','A notary verified the signatures / on the property papers / before the buyer submitted them to the land office.','notary 是核实文件签名或办理宣誓手续的公证人。','公证人核验签名后，买方才提交文件。'),M('The notary authenticated the document by changing the buyer’s signature without permission.','The notary authenticated the document after verifying the buyer’s signature.','擅自更改签名不属于核实或认证文件的职责。','meaning'),[q('What did the notary verify?','signatures on the property papers','the price of the house','the land office’s opening hours','公证人核验的是房产文件上的签名。'),q('Who should authenticate a document in this example?','a notary','a property buyer acting alone','a railway conductor','notary 指负责核验或认证文件的公证人。',1,'meaning'),q('When did the buyer submit the papers?','after the signatures were verified','before the papers were written','only after the house was demolished','签名核验完成后，买方再提交文件。',1,'context'),q('Which action would be improper for the notary?','secretly altering a signer’s name','checking that a signature is present','administering an oath where authorized','公证核验不能擅自篡改签署人的姓名。',1,'distinction')]);
P('notate','Notate is formed from Latin notare, “to mark,” and means to represent music, movement, or data with a system of signs.',C('notate.s1','用记号记录','The choreographer asked an assistant to notate each turn and pause so another company could reproduce the dance.','编舞请助手把每个转身和停顿记成舞谱，以便另一家公司重现这支舞。','The choreographer asked an assistant / to notate each turn and pause / so another company could reproduce the dance.','notate 是动词，表示用符号系统记录音乐、舞蹈动作或数据。','舞步被记录后，其他舞团可以重现。'),M('The assistant notated the dance by erasing every movement from the record.','The assistant notated the dance by recording each movement with symbols.','抹掉所有动作没有把舞蹈表示或记录下来。','meaning'),[q('What did the assistant record?','turns and pauses in the dance','the theatre’s ticket prices','the dancers’ lunch orders','助手要记下舞蹈中的转身和停顿。'),q('Which task is an example of notating?','writing musical pitches on a staff','watching a performance without recording it','building a stage without a plan','notate 指用符号系统记录信息，写音高在谱上符合此义。',1,'meaning'),q('Why should the dance be notated?','so another company can reproduce it','so the original dancers forget it','so the theatre can remove the stage','舞谱使另一家公司能够重现舞蹈。',1,'context'),q('The verb notate is historically connected with the idea of?','marking something with signs','making something tastier','cutting a notch into wood','notate 源于“标记”这一词根含义。',1,'word-formation')]);
P('notation','Notation comes from Latin notationem, “a marking or note”; it is a system of signs, especially one used for music or technical information.',C('notation.s1','符号系统；乐谱','The textbook explains the notation used for chemical reactions before asking students to balance the equations.','课本先解释化学反应所用的符号体系，再让学生配平反应方程式。','The textbook explains the notation / used for chemical reactions / before asking students to balance the equations.','notation 指用符号表示信息的一套规则，音乐和科学中都常见。','学生先了解符号规则，才能读写化学方程式。'),M('The equation used no notation because every chemical symbol was replaced with an unexplained blank.','The equation used chemical notation to represent each element and reaction.','若没有符号表示体系，就无法按题意表达元素与反应。','meaning'),[q('What does the textbook explain?','the symbols used for chemical reactions','how to clean laboratory glass','how to write a personal letter','课本解释的是化学反应符号。'),q('Which item is a notation system?','symbols on a music staff showing pitch and duration','a blank page with no signs','a list of students’ lunch choices','乐谱用符号表示音高和时值，是 notation。',1,'meaning'),q('What do students do after learning the notation?','balance the equations','erase the textbook','change the elements into instruments','理解符号后，学生要配平化学方程式。',1,'context'),q('What is the central function of notation?','representing information with an agreed set of signs','authenticating a person’s signature','measuring the depth of a pool','notation 用约定的符号表示信息。',1,'meaning')]);
P('notational','Notational is formed from notation plus -al and means relating to or using a system of signs.',C('notational.s1','记号体系相关的','The article compares two notational systems for writing the same musical rhythm on a page.','文章比较了两种在纸面上记录同一音乐节奏的记谱体系。','The article compares two notational systems / for writing the same musical rhythm / on a page.','notational 是形容词，描述与 notation 记号系统有关的事物。','两套体系都用来写下同一节奏。'),M('The article called the system notational although it contained no signs, symbols, or written representation.','The article called the symbol-based system notational.','没有符号或书写表示的体系不符合 notational 的含义。','meaning'),[q('What does the article compare?','two systems for writing a rhythm','two kinds of musical instrument','two performances with no written record','文章比较两套记谱体系。'),q('Which phrase uses notational naturally?','a notational convention for marking pitch','a notationally loud drum','a notational musician who plays the flute','notational 修饰与符号体系相关的 convention。',1,'word form'),q('What do both systems represent?','the same musical rhythm','different weather forecasts','the performers’ signatures','两种体系都用于记录同一音乐节奏。',1,'context'),q('The suffix -al changes notation into?','an adjective meaning related to notation','a verb meaning to erase notation','a noun meaning a person who signs papers','-al 构成形容词，表示“与……有关的”。',1,'word-formation')]);
P('notch','The origin of notch is uncertain in the available historical source; in current English it names a V-shaped cut or a step on a scale.',[C('notch.s1','切口；刻痕','The carpenter cut a small notch in the beam so the two wooden pieces would fit together securely.','木匠在横梁上切出一个小缺口，让两块木料能够牢固嵌合。','The carpenter cut a small notch / in the beam / so the two wooden pieces would fit together securely.','notch 作名词可指表面上的 V 形切口或刻痕。','缺口用于让木料相互嵌合。'),C('notch.s1','等级；档次','After the final safety test, the device moved up one notch on the laboratory’s reliability scale.','通过最后一项安全测试后，这台设备在实验室可靠性量表上提高了一个档次。','After the final safety test / the device moved up one notch / on the laboratory’s reliability scale.','notch 也可指量表上的一级或一个档次。','测试后设备在可靠性等级上升一级。')],M('The carpenter cut a notch into the beam by adding a smooth, unbroken layer of wood.','The carpenter cut a notch into the beam by removing a small V-shaped piece.','切口是切去表面一小部分形成的凹痕，而不是增加完整木层。','meaning'),[q('Why did the carpenter cut the notch?','to help two wooden pieces fit together','to make the beam longer','to mark a musical pitch','缺口用于让两块木料嵌合。'),q('What happened to the device’s rating?','it rose by one level','it fell off the scale','it was replaced by a wooden beam','one notch 在量表上表示一级。',1,'meaning'),q('Which object can have a notch in its surface?','a beam cut to join another piece of wood','a perfectly smooth sheet with no cut','a spoken sentence with no written marks','notch 的一个词义是表面上的切口或刻痕。',1,'context'),q('On a rating scale, “one notch” most nearly means?','one step or level','one entire machine','one river crossing','在量表语境中，notch 指一级或一个档次。',1,'meaning')]);
P('note','Note comes from Latin nota, “mark or sign”; it can mean a short written message, a musical sound or tone, paper money, or the act of noticing or recording.',[C('note.s1','便条；笔记','Before leaving the workshop, I left a note telling the evening technician where the spare keys were stored.','离开车间前，我留了张便条，告诉晚班技术员备用钥匙放在哪里。','Before leaving the workshop / I left a note / telling the evening technician where the spare keys were stored.','note 作名词可指简短的书面留言或备忘。','便条把钥匙存放位置告知晚班同事。'),C('note.s2','音符；音调','The singer held the final note until the conductor lowered her hand.','指挥放下手时，歌手才结束最后一个音符。','The singer held the final note / until the conductor lowered her hand.','note 也指单个乐音或声音所带的语气。','歌手延长的是一段乐音。'),C('note.s3','纸币','The cashier checked the security strip on the bank note before placing it in the till.','收银员把纸币放入钱柜前检查了上面的安全线。','The cashier checked the security strip / on the bank note / before placing it in the till.','英式英语 note 可指纸币。','安全线是纸币的防伪特征。'),C('note.s4','注意；记下','Please note the revised gate number before you board the train.','上火车前请记下更改后的登机口编号。','Please note the revised gate number / before you board the train.','note 可作动词，表示注意到或把信息记下来。','旅客需要记住新的编号。')],M('The conductor told the singer to hold the final note, but she stopped the sound before singing it.','The conductor told the singer to hold the final note, and she sustained the sound.','hold a note 指延长该音符或音调，停唱并未做到这一点。','meaning'),[q('What information did the workshop note contain?','where the spare keys were stored','when the singer’s concert began','which bank note was counterfeit','便条写明备用钥匙的位置。'),q('What did the singer hold?','the final musical sound','a paper bank note','a written message','音乐语境中的 note 是一个乐音。',2,'meaning'),q('What did the cashier inspect?','the security strip on a bank note','a note left in the workshop','the train gate number','收银员检查纸币上的防伪安全线。',3,'context'),q('In “Please note the revised gate number,” note means?','pay attention to it or record it','sing it for a long time','exchange it for cash','此处 note 是动词，表示注意或记下信息。',4,'meaning')]);
P('notebook','Notebook combines note and book; it can mean a small book for writing or a portable computer.',[C('notebook.s1','笔记本','The geology student sketched each rock layer in a notebook during the field survey.','地质专业学生在野外调查时把每一层岩石都画在笔记本里。','The geology student sketched each rock layer / in a notebook / during the field survey.','notebook 的常见义是用来写笔记或绘图的小本子。','学生把野外观察画进本子中。'),C('notebook.s2','笔记本电脑','She opened her notebook computer in the station lobby and uploaded the survey photographs before boarding.','她在车站大厅打开笔记本电脑，登车前上传了调查照片。','She opened her notebook computer / in the station lobby / and uploaded the survey photographs before boarding.','notebook 也可指便携式电脑，常见搭配是 notebook computer。','上传照片和打开电脑表明此处是电子设备。')],M('The student uploaded photographs by writing them into the paper notebook with a pen.','The student uploaded photographs using a notebook computer.','纸质笔记本不能上传文件；此处应使用便携电脑。','distinction'),[q('Where did the student sketch the rock layers?','in a paper notebook','on the station computer','on the train window','野外调查时，她把岩层画进笔记本。'),q('Which notebook can upload digital photographs?','a notebook computer','a blank paper notebook','a rock layer','上传数字照片需要笔记本电脑。',2,'distinction'),q('When did she upload the photographs?','before boarding','after the train reached the final station','before the field survey began','句子说她登车前上传照片。',2,'context'),q('What does notebook combine in its formation?','note and book','north and boat','number and token','notebook 由 note 与 book 组合而成。',1,'word-formation')]);
P('noted','Noted is the past participle of note used adjectivally to mean well known or distinguished.',C('noted.s1','著名的；知名的','The museum invited a noted conservationist to explain how the restored wetlands support migratory birds.','博物馆邀请一位著名的自然保护专家讲解修复后的湿地如何支持候鸟。','The museum invited a noted conservationist / to explain / how the restored wetlands support migratory birds.','noted 作形容词修饰人或事物，表示知名、受到认可。','博物馆邀请的专家因保护工作而知名。'),M('The museum called the speaker noted because nobody had heard of her and her work was unknown.','The museum called the speaker noted because she was widely respected for her conservation work.','noted 表示知名或受认可，与完全无人知晓相矛盾。','meaning'),[q('Who was invited to the museum?','a well-known conservationist','a visiting train driver','a newly planted wetland','noted conservationist 指知名的自然保护专家。'),q('Which person could be described as noted?','a researcher widely recognized for major discoveries','a person whose work is unknown to everyone','someone who has not taken any notes','noted 表示受到广泛认识或认可。',1,'meaning'),q('What did the guest explain?','how restored wetlands support migratory birds','how to repair the museum’s roof','how to write a bank note','专家讲解湿地如何支持候鸟。',1,'context'),q('In this sentence, noted is functioning as?','an adjective describing the conservationist','a noun naming a notebook','a verb meaning to erase','noted 在此修饰名词 conservationist。',1,'grammar')]);
P('notepad','Notepad combines note and pad and names a small pad of blank paper used for writing brief notes.',C('notepad.s1','便笺本','The dispatcher kept a notepad beside the radio to record each delivery address as it came in.','调度员把便笺本放在无线电旁，随时记下每个送货地址。','The dispatcher kept a notepad beside the radio / to record each delivery address / as it came in.','notepad 指用于简短书写的便笺本或纸张。','调度员收到地址后记在纸上。'),M('The dispatcher recorded the delivery address on the notepad by uploading the voice file to a cloud server.','The dispatcher wrote the delivery address on the notepad.','notepad 是纸质书写用品；上传语音文件并不是在本子上记录。','distinction'),[q('What did the dispatcher record?','delivery addresses','radio frequencies only','the paper’s color','便笺本用来记录收到的送货地址。'),q('Which object is a notepad?','a small pad of blank paper for quick notes','a portable computer used to upload files','a book of printed maps','notepad 指小型书写纸本。',1,'meaning'),q('Where did the dispatcher keep it?','beside the radio','inside the delivery truck’s engine','on the museum wall','句子说便笺本放在无线电旁。',1,'context'),q('Which word parts form notepad?','note + pad','not + head','north + page','notepad 由 note 与 pad 组合。',1,'word-formation')]);
P('notes','Notes is the plural of note; it can mean written records of a lesson or talk, and music written on a page.',[C('notes.s1','记录；课堂笔记','The students compared their notes after the lecture to check the dates and definitions they had written down.','讲座后，学生们互相核对笔记中的日期和定义。','The students compared their notes / after the lecture / to check the dates and definitions they had written down.','notes 可指记录谈话或课程内容的笔记。','学生们用笔记核对信息。'),C('notes.s1','乐谱','The pianist placed the notes for the new piece on the stand and marked the bars that needed practice.','钢琴家把新曲乐谱放在谱架上，并标出需要练习的小节。','The pianist placed the notes for the new piece / on the stand / and marked the bars that needed practice.','notes 也可指写在纸上的乐音或乐谱。','谱架和小节练习表明 notes 指乐谱。')],M('The students compared their notes, but each page contained only blank paper with no written record.','The students compared the written notes they had made during the lecture.','空白页没有可供核对的笔记内容。','meaning'),[q('What did the students check in their notes?','dates and definitions','the pianist’s shoe size','a list of delivery addresses','他们核对讲座笔记中的日期和定义。'),q('Where did the pianist place the notes?','on the music stand','inside the radio','in the dispatcher’s engine','乐谱放在谱架上。',1,'context'),q('Which sentence uses notes to mean lesson records?','I reviewed my notes before the history exam.','The pianist placed the notes on the music stand.','She held one note for four beats.','复习考试的 notes 指课堂记录。',1,'meaning'),q('What do the pianist’s notes contain?','written music divided into bars','addresses from a delivery route','blank sheets without symbols','小节与谱架说明此处 notes 是书写的乐谱。',1,'meaning')]);
P('noteworthy','Noteworthy combines note and worthy and means important or interesting enough to deserve attention or mention.',[C('noteworthy.s1','显著；值得注意','A noteworthy decline in hospital infections followed the introduction of the new cleaning protocol.','采用新的清洁规程后，医院感染率显著下降。','A noteworthy decline / in hospital infections / followed the introduction of the new cleaning protocol.','noteworthy 修饰 decline，强调变化重要或值得关注。','清洁规程实施后感染率明显下降。'),C('noteworthy.s2','值得一提','One noteworthy detail in the report is that every volunteer completed the year-long survey.','报告中值得一提的一点是，每位志愿者都完成了为期一年的调查。','One noteworthy detail in the report / is that every volunteer / completed the year-long survey.','noteworthy 也可表示某个细节值得在报告或谈话中提及。','后面的从句具体说明值得提及的细节。')],M('The editor marked the discovery noteworthy because it was trivial, already known, and irrelevant to the study.','The editor marked the discovery noteworthy because it was important to the study.','无关紧要且早已知晓的发现不符合 noteworthy 的“值得注意”含义。','meaning'),[q('What followed the new cleaning protocol?','a significant fall in hospital infections','a year-long survey of train tickets','an increase in volunteer absences','报告说医院感染率下降。'),q('What detail is singled out in the report?','all volunteers completed the year-long survey','the editor misplaced the report','the hospital changed its name','worth mentioning 的细节是所有志愿者完成了调查。',2,'context'),q('Which result is most noteworthy?','a treatment that sharply reduces a dangerous infection','a routine result with no measurable effect','a fact unrelated to the research question','noteworthy 指重要或有趣、值得关注的事。',1,'meaning'),q('In the second example, noteworthy means?','deserving mention in a report','not written down anywhere','worthy of a paper notebook','noteworthy 可指值得在报告中提到。',2,'meaning')]);
P('nothing','Nothing combines no and thing and means not anything; in expressions such as for nothing, it can mean without payment or with no result.',[C('nothing.s1','没有任何东西','The inspector opened every cupboard but found nothing that could explain the laboratory’s missing samples.','检查员打开了所有柜子，却没有找到任何能解释实验室样本失踪的东西。','The inspector opened every cupboard / but found nothing / that could explain the laboratory’s missing samples.','nothing 作代词表示没有任何东西，通常作单数看待。','检查所有柜子仍一无所获。'),C('nothing.s2','免费；无关紧要','The museum offered the children’s workshop for nothing, and the small delay meant nothing once the doors opened.','博物馆免费提供儿童工作坊；开门后，那点小延误也无关紧要了。','The museum offered the children’s workshop for nothing / and the small delay meant nothing / once the doors opened.','for nothing 可表示免费；mean nothing 可表示无关紧要。','两个固定用法分别表达免费与不重要。')],M('The inspector found nothing that explain the samples’ disappearance.','The inspector found nothing that explained the samples’ disappearance.','nothing 作单数先行词，关系从句谓语应用 explained。','grammar'),[q('What did the inspector find in the cupboards?','nothing that explained the missing samples','a complete set of missing samples','a notice about a free workshop','检查员没有找到能解释样本失踪的东西。'),q('What does “for nothing” mean in the workshop example?','without paying','for no reason at all','with nothing to do','for nothing 在此表示免费。',2,'meaning'),q('When did the delay stop mattering?','once the museum doors opened','before the workshop was planned','after every cupboard was emptied','开门后，小延误就不再重要。',2,'context'),q('Which verb agrees with “nothing” in standard English?','Nothing remains in the box.','Nothing remain in the box.','Nothing are remaining in the box.','nothing 作单数代词，谓语用 remains。',1,'grammar')]);
P('notice','Notice comes from Latin notitia, “knowledge,” related to noscere, “to know”; it can mean to become aware, a formal advance statement, or a posted announcement.',[C('notice.s1','注意；察觉','The technician noticed a faint crack in the glass before the pressure test began.','压力测试开始前，技术员注意到玻璃上有一道细微裂纹。','The technician noticed a faint crack / in the glass / before the pressure test began.','notice 作动词表示通过感官察觉到某人或某物。','裂纹在测试前被发现。'),C('notice.s2','正式通知；预告','Tenants must give the landlord one month’s notice before ending the lease.','租户结束租约前必须提前一个月通知房东。','Tenants must give the landlord one month’s notice / before ending the lease.','notice 作名词可指提前发出的正式通知或预告。','notice 提前一个月告知租约终止。'),C('notice.s3','布告；启事','A notice beside the lift announced that the north entrance would close for repairs.','电梯旁的布告宣布北入口将关闭维修。','A notice beside the lift / announced / that the north entrance would close for repairs.','notice 也指张贴出来供人阅读的告示。','布告告知入口维修安排。')],M('Tenants gave the landlord notice after the lease ended, although the contract required one month’s advance warning.','Tenants gave the landlord one month’s notice before ending the lease.','notice 必须提前一个月发出，租约结束后才通知不符合约定。','context'),[q('What did the technician become aware of?','a faint crack in the glass','a month of rent in cash','a sign beside the lift','notice 作动词时表示注意到裂纹。'),q('How much advance warning must tenants give?','one month','one day','one year','租户必须提前一个月通知。',2,'context'),q('What did the posted notice announce?','the north entrance would close for repairs','the lease had been extended','the pressure test was complete','张贴的告示宣布北入口将维修关闭。',3,'meaning'),q('Which use of notice is a verb meaning “become aware of”?','She noticed the crack before the test.','She posted a notice by the lift.','She gave one month’s notice.','第一句中的 noticed 表示察觉到。',1,'meaning')]);
P('noticeable','Noticeable is formed from notice plus -able and describes something easy to see, hear, or otherwise detect.',C('noticeable.s1','显而易见的','There was a noticeable improvement in the seedlings after the greenhouse received more daylight.','温室获得更多日照后，幼苗有了明显改善。','There was a noticeable improvement / in the seedlings / after the greenhouse received more daylight.','noticeable 作形容词修饰 improvement，表示容易察觉。','日照增加后，幼苗变化明显。'),M('The improvement was noticeable because nobody could see or measure any change in the seedlings.','The improvement was noticeable because the seedlings grew taller and greener.','完全看不出或测不出变化，不能称为 noticeable。','meaning'),[q('What changed after the greenhouse received more daylight?','the seedlings improved','the roof became smaller','the gardeners left the site','句子说幼苗有了改善。'),q('Which change would be noticeable?','a clearly visible increase in a plant’s height','a difference too small for anyone to detect','a hidden change that leaves no trace','noticeable 指容易看到或察觉的。',1,'meaning'),q('What is noticeable in the example?','the improvement in the seedlings','the greenhouse’s original blueprint','the number of clouds outside','例句聚焦幼苗的明显改善。',1,'context'),q('What does the suffix -able contribute here?','the sense “able to be noticed”','the sense “a person who gives notice”','the sense “not having a notice”','-able 表示“能够被……”，noticeable 即容易被注意到。',1,'word-formation')]);
P('noticeably','Noticeably is formed from noticeable plus -ly and means in a way that is easy to see or significant enough to attract attention.',[C('noticeably.s1','显著地','The redesigned filter reduced the amount of dust in the workshop noticeably within the first week.','重新设计的过滤器在第一周内就显著减少了车间粉尘。','The redesigned filter reduced the amount of dust / in the workshop noticeably / within the first week.','noticeably 作副词修饰 reduced，表示减少幅度明显。','一周内粉尘减少到容易察觉的程度。'),C('noticeably.s2','值得注意地','The new map is noticeably easier for first-time visitors to follow than the old one.','新地图比旧地图更便于初次到访者阅读，这一点值得注意。','The new map is noticeably easier / for first-time visitors to follow / than the old one.','noticeably 也可强调某种程度值得特别留意。','句子比较两张地图的易读程度。')],M('Dust fell noticeably after the filter was changed, but the recorded amount did not change at all.','Dust fell noticeably after the filter was changed, and the recorded amount dropped substantially.','没有任何测量变化与“显著减少”互相矛盾。','meaning'),[q('What did the new filter reduce?','the amount of workshop dust','the number of maps','the visitors’ walking speed','过滤器减少了车间粉尘。'),q('Which comparison is noticeably in the second sense?','the new map is easier to follow than the old one','both maps are blank and identical','visitors cannot enter the building','noticeably 可强调值得留意的明显差异。',2,'distinction'),q('How soon was the dust reduction observed?','within the first week','after a full year','before the filter was installed','例句说第一周内就有明显效果。',1,'context'),q('Noticeably is most closely related to which adjective?','noticeable','notional','notorious','noticeably 是 noticeable 加 -ly 构成的副词。',1,'word-formation')]);
P('notification','Notification is formed from notify plus -cation and means a written or spoken message that informs someone about something.',C('notification.s1','通知；告知','A notification appeared on the control panel to tell the operator that the water level had reached its limit.','控制面板上弹出一条通知，告知操作员水位已达到上限。','A notification appeared on the control panel / to tell the operator / that the water level had reached its limit.','notification 是传达信息的通知或告知消息。','屏幕消息提醒操作员注意水位。'),M('The panel sent a notification but gave the operator no message or information at all.','The panel sent a notification informing the operator that the water level had reached its limit.','notification 本身就是传达信息的消息，完全没有内容与该词义矛盾。','meaning'),[q('Where did the notification appear?','on the control panel','inside the water pipe','on a paper bank note','通知出现在控制面板上。'),q('What did the notification tell the operator?','the water level had reached its limit','the map was easier to read','the filter was made of glass','通知内容是水位达到上限。',1,'context'),q('Which item is a notification?','a message alerting a user to a completed payment','an empty screen with no text or signal','a person’s private belief','notification 是告知某事的消息或提示。',1,'meaning'),q('Which word is the base of notification?','notify','notch','nourish','notification 由 notify 派生而来。',1,'word-formation')]);
P('notify','Notify comes from Latin notificare, “to make known”; it means to inform someone officially or report a fact to an authority.',[C('notify.s1','正式通知','The school will notify parents by email if the field trip is postponed because of severe weather.','如果恶劣天气导致野外活动延期，学校会通过邮件正式通知家长。','The school will notify parents by email / if the field trip is postponed / because of severe weather.','notify 后常接被通知的人，再接通知内容。','学校负责向家长传达延期消息。'),C('notify.s2','向机构申报','Researchers must notify the safety office of any chemical spill immediately.','研究人员必须立即向安全办公室报告任何化学品泄漏。','Researchers must notify the safety office / of any chemical spill / immediately.','notify 也可表示向有权处理的机构报告事实。','泄漏事件需要上报安全部门。')],M('The school will notify to parents that the trip has been postponed.','The school will notify parents that the trip has been postponed.','notify 作“通知某人”时直接接人作宾语，不用 to。','grammar'),[q('How will the school contact parents?','by email','by changing the trip route silently','through a newspaper advertisement only','学校会通过邮件通知家长。'),q('Who must be told about a chemical spill?','the safety office','the field trip’s passengers only','the map designer','研究人员须向安全办公室报告泄漏。',2,'context'),q('Which sentence uses notify with its reporting sense?','The lab notified the safety office of the spill.','The lab noticed a spill on the floor.','The lab left a note in a notebook.','notify ... of 报告某事给负责机构。',2,'meaning'),q('Which construction is correct?','notify parents of a delay','notify to parents a delay','notify a delay to parents','notify 后直接接被通知者。',1,'grammar')]);
P('notion','Notion comes from Latin notionem, “a concept or idea”; it can mean a belief or understanding, or a sudden wish or plan.',[C('notion.s1','概念；看法','The team rejected the notion that a single test could prove the river was safe for every species.','团队否定了仅凭一次测试就能证明这条河对所有物种都安全的看法。','The team rejected the notion / that a single test could prove / the river was safe for every species.','notion 可指关于某事的观念、想法或信念。','团队质疑测试结果能否支撑这种看法。'),C('notion.s2','突然的念头','On a sudden notion, Lena cycled to the coast before sunrise to watch the first fishing boats return.','莱娜突然想到一个主意，便在日出前骑车到海边看第一批渔船返航。','On a sudden notion / Lena cycled to the coast / before sunrise to watch the first fishing boats return.','a notion 可指突然产生的愿望或行动计划。','on a sudden notion 表明行动源于临时起意。')],M('The report presented the notion that the river was safe, but it gave no test results or supporting evidence.','The report presented the notion that the river was safe and supported it with test results.','无依据的断言不能冒充已有证据支撑的观念。','meaning'),[q('What belief did the team reject?','that one test proved the river safe for every species','that fishing boats return before sunrise','that all rivers contain salt','团队否定的是一次测试能证明河流对所有物种安全。'),q('Why did Lena cycle to the coast before sunrise?','a sudden idea prompted her to watch the boats','she had to notify the safety office','the river had become a notion','sudden notion 在此表示突然产生的主意。',2,'context'),q('Which sentence uses notion to mean an idea or belief?','They questioned the notion that the bridge was harmless.','She had a notion to visit the harbor on a whim.','The map showed a notch in the coast.','第一句中 notion 指一种看法或观念。',1,'meaning'),q('In “on a sudden notion,” the word suggests?','an unexpected wish or plan','a formal written notice','a measured quantity of water','该搭配表示突然产生的念头或计划。',2,'meaning')]);
P('notional','Notional combines notion with -al and means theoretical, based on an idea, or used as an estimated rather than actual amount.',C('notional.s1','概念的；名义估算的','The accountant used a notional value of $500 to compare the two plans, although no payment had actually been made.','会计用 500 美元的名义估值比较两种方案，尽管实际上并未付款。','The accountant used a notional value / of $500 / to compare the two plans.','notional 描述理论上或为估算而设定的数值，不表示实际支付。','500 美元是比较方案的估算值。'),M('The report called $500 a notional payment and then claimed that the customer had actually transferred that exact sum.','The report used $500 as a notional value for comparison, not as a payment actually made.','notional 数值是理论或估算值，不能同时说它已真实转账。','distinction'),[q('Was the $500 actually paid?','No, it was an estimated comparison value.','Yes, it was transferred to the accountant.','It was the price of a notebook.','句子说 500 美元只是名义估值，未实际付款。'),q('Which amount is notional?','an estimated figure used to compare plans','a sum confirmed in a bank transfer','cash counted in a till','notional 可以指估算用途的理论数值。',1,'meaning'),q('Why did the accountant use the value?','to compare two plans','to pay the customer’s rent','to calculate the river’s depth','该数值用来比较方案。',1,'context'),q('The suffix -al makes notional an adjective meaning?','related to a notion or theoretical estimate','the act of sending a notice','a person who records music','notional 是描述观念或理论估算的形容词。',1,'word-formation')]);
P('notoriety','Notoriety comes from Latin notorius, “well known”; in modern use it usually means fame for a bad reason.',C('notoriety.s1','恶名；臭名','The company gained notoriety after investigators found that it had dumped waste into the protected wetlands.','调查人员发现该公司向受保护湿地倾倒废物后，它声名狼藉。','The company gained notoriety / after investigators found / that it had dumped waste into the protected wetlands.','notoriety 通常指因负面行为而出名。','污染行为导致公司获得恶名。'),M('The firm gained notoriety for its generous rescue work and was praised by every community it helped.','The firm gained a good reputation for its rescue work and avoided notoriety.','notoriety 通常是负面名声，不能用来表示因善行而获赞誉。','distinction'),[q('Why did the company gain notoriety?','it dumped waste in protected wetlands','it rescued every injured bird','it planted a public garden','公司因向受保护湿地倾倒废物而声名狼藉。'),q('Which event could bring notoriety?','a scandalous act widely criticized by the public','a quiet achievement known only to its maker','an ordinary day with no public attention','notoriety 指因坏事而广为人知。',1,'meaning'),q('Who discovered the waste dumping?','investigators','the company’s gardeners','the museum’s pianist','调查人员发现了倾倒废物的行为。',1,'context'),q('How does notoriety differ from neutral fame?','it usually carries a negative reason for being known','it always means a person is unknown','it refers only to a written notification','notoriety 通常带有负面原因或评价。',1,'distinction')]);
P('notorious','Notorious comes from Latin notorius, “well known,” and now usually describes someone or something famous for a bad quality or disliked habit.',[C('notorious.s1','声名狼藉的','The factory became notorious for releasing untreated water into the river despite repeated warnings.','尽管屡次收到警告，这家工厂仍排放未经处理的污水，因此声名狼藉。','The factory became notorious / for releasing untreated water / despite repeated warnings.','notorious 作形容词表示因坏事而臭名昭著。','无视警告排污是其恶名的原因。'),C('notorious.s2','出了名……的','That trail is notorious for sudden fog, so hikers carry a compass even on clear mornings.','那条步道以突发浓雾而出名，因此徒步者即使在晴朗早晨也带指南针。','That trail is notorious for sudden fog / so hikers carry a compass / even on clear mornings.','notorious for 可描述广为人知且通常令人不快的特点。','浓雾是这条步道的著名风险。')],M('The factory was notorious for releasing clean water, and everyone praised it for avoiding pollution.','The factory was notorious for releasing untreated water, and residents criticized its pollution.','因排污而臭名昭著与受赞扬保护环境相矛盾。','meaning'),[q('Why was the factory notorious?','it released untreated water','it repaired the river bridge','it reduced pollution to zero','工厂因排放未经处理的水而臭名昭著。'),q('What is the trail notorious for?','sudden fog','a shortage of maps','a nearby music school','步道以突发浓雾而闻名。',2,'context'),q('Which use of notorious is correct?','The road is notorious for dangerous winter ice.','The road is notorious for being perfectly safe and uneventful.','The road is notorious a map.','notorious for 后可接广为人知的负面特点。',2,'grammar'),q('What does notorious usually imply about a reputation?','people know it for something bad or unwelcome','people have never heard of it','it is praised for every action','notorious 通常指因负面特征而出名。',1,'meaning')]);
P('notoriously','Notoriously is formed from notorious plus -ly; it can mean in a way famous for something bad, or as is widely known.',[C('notoriously.s1','臭名昭著地','The road is notoriously dangerous in winter because black ice forms on its shaded bends.','这条路冬季以危险出名，因为背阴弯道会结黑冰。','The road is notoriously dangerous in winter / because black ice forms / on its shaded bends.','notoriously 修饰 dangerous，强调危险特点广为人知。','黑冰解释了这条路的恶名。'),C('notoriously.s2','众所周知地','The archive’s oldest map is notoriously difficult to unfold without damaging its brittle edges.','众所周知，档案馆最古老的地图很难展开，否则容易损坏脆弱的边缘。','The archive’s oldest map is notoriously difficult to unfold / without damaging / its brittle edges.','notoriously 也可表示某种情况众所周知。','地图容易受损是大家都知道的难题。')],M('The mountain road was notoriously safe in winter because its shaded bends were covered with black ice.','The mountain road was notoriously dangerous in winter because its shaded bends were covered with black ice.','结黑冰的弯道带来危险，与“安全”相矛盾。','meaning'),[q('Why is the road notoriously dangerous?','black ice forms on shaded bends','the archive stores an old map','the road is closed every summer','背阴弯道结黑冰是道路危险的原因。'),q('What is notoriously difficult to unfold?','the archive’s oldest map','a paper ticket from the station','a safety notice on the wall','例句说最古老的地图很难展开。',2,'context'),q('Which meaning fits “notoriously difficult”?','widely known to be difficult','difficult for exactly one person only','not difficult at all','notoriously 可表示“众所周知地”。',2,'meaning'),q('What does the suffix -ly make notoriously?','an adverb from the adjective notorious','a noun naming a public notice','a verb meaning to notify','-ly 将 notorious 转为副词 notoriously。',1,'word-formation')]);
P('notwithstanding','Notwithstanding is formed from not and withstanding; as a preposition it means in spite of, and as an adverb it means nevertheless.',[C('notwithstanding.s1','尽管；虽然','Notwithstanding the heavy rain, the rescue team reached the village before nightfall.','尽管下着大雨，救援队仍在天黑前抵达村庄。','Notwithstanding the heavy rain / the rescue team reached the village / before nightfall.','作介词时 notwithstanding 后接名词短语，表示“尽管”。','大雨没有阻止救援队及时到达。'),C('notwithstanding.s2','仍然；还是','The inspection found several faults; the machine, notwithstanding, continued to run until it was safely shut down.','检查发现了几处故障；尽管如此，机器仍继续运行，直到被安全关闭。','The inspection found several faults / the machine, notwithstanding, continued to run / until it was safely shut down.','作副词时 notwithstanding 表示 nevertheless，常用于较正式语体。','后半句表示机器仍继续运行。')],M('Notwithstanding the heavy rain, but the rescue team reached the village before nightfall.','Notwithstanding the heavy rain, the rescue team reached the village before nightfall.','notwithstanding 已引出让步状语，不再与 but 重复连接。','grammar'),[q('What condition did the rescue team overcome?','heavy rain','a broken music stand','a missing bank note','notwithstanding 后接 heavy rain，说明救援队冒雨前进。'),q('What did the machine do despite faults?','it continued running until safely shut down','it immediately reached the village','it was never inspected','机器仍运行到安全关闭为止。',2,'context'),q('Which sentence uses notwithstanding as a preposition?','Notwithstanding the delay, the train arrived before noon.','The train was delayed, notwithstanding it arrived before noon.','The train notwithstanding to arrive before noon.','介词用法后接名词短语 the delay。',1,'grammar'),q('As an adverb, notwithstanding is closest in meaning to?','nevertheless','because of','at the same time as','副词用法表示“尽管如此；仍然”。',2,'meaning')]);
P('nought','Nought is an older British English word for zero, especially in numbers and expressions such as “all for nought.”',C('nought.s1','零','The scoreboard showed three-nought after the visiting team scored its third goal without reply.','客队连进三球而对方未得分，记分牌显示三比零。','The scoreboard showed three-nought / after the visiting team scored its third goal / without reply.','nought 表示数字 0，英国英语中尤常见于比分读法。','主队没有进球，比分为三比零。'),M('The referee recorded the score as three-nought because both teams had scored three goals.','The referee recorded the score as three-all because both teams had scored three goals.','两队各进三球应为 3 比 3，而不是 3 比 0。','number'),[q('What score did the board show?','three to zero','three to three','zero to three','three-nought 表示三比零。'),q('Which number is nought?','0','3','30','nought 是零。',1,'number'),q('Which team scored three times without reply?','the visiting team','the home team','neither team','客队进了三球，对方没有进球。',1,'context'),q('In British usage, nought is often read as?','zero','nine','one hundred','nought 是 zero 的一种说法。',1,'meaning')]);
P('noun','Noun comes through French from Latin nomen, “name”; it names a person, place, thing, quality, or idea, and also the grammatical class of such words.',[C('noun.s1','表示人或事物的词','In “The river flooded,” river is the noun naming the place whose banks overflowed.','在“The river flooded”中，river 是表示发生漫堤的河流的名词。','In “The river flooded” / river is the noun / naming the place whose banks overflowed.','noun 可指表示人、地点、事物、性质或想法的词。','river 是句中指地点的词。'),C('noun.s2','名词词类','The teacher asked the class to sort each word into a grammatical category and identify every noun.','老师让全班把每个词按语法类别分类，并找出所有名词。','The teacher asked the class / to sort each word into a grammatical category / and identify every noun.','noun 也可指语法中的名词词类。','任务明确要求从不同词类中找出名词。')],M('In “The river flooded,” the word river is a verb because it names the place.','In “The river flooded,” the word river is a noun because it names the place.','river 表示地点，是名词，不是表示动作的动词。','grammar'),[q('Which word is the noun in “The river flooded”?','river','flooded','the','river 是表示地点的名词。'),q('What did the teacher ask the class to identify?','words in the noun category','only punctuation marks','the river’s water level','老师让学生识别名词这一语法类别。',2,'context'),q('Which word is a noun naming a quality?','honesty','quickly','beneath','名词可以表示性质，honesty 是表示品质的名词。',1,'meaning'),q('What is the Latin source word related to noun?','nomen, meaning “name”','notare, meaning “mark”','noscere, meaning “to know”','noun 与拉丁语 nomen“名称”有关。',1,'word-formation')]);
P('nourish','Nourish comes through Old French from Latin nutrire, “to feed or foster”; it means to provide food for growth or to sustain an idea or feeling.',[C('nourish.s1','滋养；供给营养','The garden’s rich soil and steady rain nourish the young apple trees through the dry season.','肥沃的土壤和稳定的雨水滋养着幼苹果树，使它们度过旱季。','The garden’s rich soil and steady rain / nourish the young apple trees / through the dry season.','nourish 作动词表示供给生长所需的营养或条件。','土壤和雨水帮助幼树成长。'),C('nourish.s2','培养；维持想法','The community meetings nourished a hope that the abandoned station could become a public library.','社区会议培养了人们把废弃车站改成公共图书馆的希望。','The community meetings nourished a hope / that the abandoned station / could become a public library.','nourish 也可比喻为想法或感情提供持续支持。','会议使改建图书馆的希望得以延续。')],M('The dry soil nourished the young trees by withholding all water and nutrients from their roots.','The fertile soil nourished the young trees by supplying water and nutrients to their roots.','不给水和养分无法滋养树木。','meaning'),[q('What nourished the apple trees?','rich soil and steady rain','an abandoned railway station','a public library notice','土壤和雨水为幼树提供生长条件。'),q('What hope did the meetings nourish?','that the station could become a library','that the orchard would be removed','that the rain would stop forever','社区会议支持了改建图书馆的希望。',2,'context'),q('Which use is figurative?','Their conversations nourished her confidence.','The soil nourished the seedlings.','Rain nourished the garden.','对话“滋养”信心是比喻用法。',2,'meaning'),q('What is the older Latin source nutrire associated with?','feeding or fostering','counting to zero','writing musical notes','nourish 的词源与喂养、培育有关。',1,'word-formation')]);
P('nourishing','Nourishing is the present participle and adjective from nourish; it describes food or experience that supports healthy growth.',[C('nourishing.s1','有营养的','The clinic served a nourishing soup made with beans, vegetables, and whole grains after the long hike.','长途徒步后，诊所提供了用豆类、蔬菜和全谷物制作的营养汤。','The clinic served a nourishing soup / made with beans, vegetables, and whole grains / after the long hike.','nourishing 作形容词表示能提供营养、帮助身体健康的。','汤里含有多种营养食材。'),C('nourishing.s2','滋养心灵的','The quiet reading group became a nourishing part of the week because members shared thoughtful stories and support.','安静的读书小组因成员分享有启发的故事并互相支持，成了每周一项滋养心灵的活动。','The quiet reading group became a nourishing part of the week / because members shared thoughtful stories / and support.','nourishing 也可比喻能带来精神成长或满足。','故事分享和支持让活动对成员有益。')],M('The nourishing meal helped the hikers recover because it contained no food or energy at all.','The nourishing meal helped the hikers recover because it supplied useful nutrients and energy.','完全没有食物和能量的餐食不能称为 nourishing。','meaning'),[q('What ingredients made the soup nourishing?','beans, vegetables, and whole grains','paper notes and a compass','only water with no food','这些食材提供营养。'),q('Why was the reading group nourishing?','members shared thoughtful stories and support','the group served a bowl of soup','the group had no conversation','此处是精神层面的滋养，来自故事分享和支持。',2,'context'),q('Which example uses nourishing literally?','a balanced meal that supplies nutrients','a discussion that gives someone hope','a story that comforts a reader','身体获得营养的饭菜是字面用法。',1,'meaning'),q('Nourishing is related to which verb?','nourish','notify','notate','nourishing 是 nourish 的 -ing 形式。',1,'word-formation')]);
P('nourishment','Nourishment comes from nourish plus -ment and means food or the act of receiving what is needed to stay healthy.',C('nourishment.s1','食物；滋养','The seedlings received enough nourishment from the compost to develop strong roots before planting outdoors.','幼苗从堆肥中获得了足够养分，在移栽到户外前长出了强壮根系。','The seedlings received enough nourishment / from the compost / to develop strong roots before planting outdoors.','nourishment 作名词指维持健康或生长所需的食物和营养。','堆肥提供养分，帮助幼苗长根。'),M('The seedlings grew strong roots without any nourishment, food, water, or nutrients.','The seedlings grew strong roots after receiving nourishment from compost, water, and nutrients.','植物生长需要养分和水分，不能说完全没有任何滋养。','meaning'),[q('What did the seedlings receive from the compost?','nourishment','a notice about a library','a musical notation system','堆肥为幼苗提供养分。'),q('What developed after the seedlings received nourishment?','strong roots','a bank note','a new railway station','获得营养后幼苗长出强壮根系。',1,'context'),q('Which source provides nourishment to a growing plant?','nutrient-rich compost','a blank notepad','a loud musical note','堆肥中的营养物质可滋养植物。',1,'meaning'),q('What does -ment do in nourishment?','forms a noun related to the act or result of nourishing','turns the word into a past-tense verb','marks a plural noun','-ment 构成与滋养行为或结果相关的名词。',1,'word-formation')]);
P('nouveau','Nouveau is a French loan meaning “new”; in English it appears especially in phrases such as nouveau riche for people who have recently acquired wealth.',C('nouveau.s1','新近的','The guide described the district’s nouveau galleries as spaces opened by a new generation of artists.','导览员把该区新近开设的画廊称为 nouveau galleries，它们由新一代艺术家创办。','The guide described the district’s nouveau galleries / as spaces opened / by a new generation of artists.','nouveau 是法语借词，意为“新的”，常见于固定表达或较正式描述。','画廊是新一代艺术家近期创办的。'),M('The guide called the galleries nouveau because they had stood unchanged for centuries and had just closed.','The guide called the recently opened galleries nouveau.','几个世纪未变且已经关闭的画廊不能描述为新近出现。','meaning'),[q('Who opened the galleries?','a new generation of artists','the old railway company','a group of notaries','导览员说画廊由新一代艺术家创办。'),q('What does French nouveau mean?','new','not famous','zero','nouveau 的法语基本义是“新”。',1,'meaning'),q('Which phrase is a familiar English use of nouveau?','nouveau riche','not ever rich','nought riche','nouveau riche 是英语中常见的固定表达。',1,'word-formation'),q('Why did the guide describe these galleries as nouveau?','they had recently been opened','they had been empty for centuries','they displayed only old maps','它们是近期由新一代艺术家开设的。',1,'context')]);
P('novel','Novel comes through French from Latin novellus, “new”; as a noun it is a long fictional story, and as an adjective it means new or original.',[C('novel.s1','长篇小说','The novel follows a young surveyor who discovers an old railway tunnel beneath the city.','这部长篇小说讲述一位年轻测绘员发现城市地下旧铁路隧道的故事。','The novel follows a young surveyor / who discovers an old railway tunnel / beneath the city.','novel 作名词指篇幅较长的虚构故事。','人物与连续情节构成长篇小说。'),C('novel.s2','新颖的','The engineers proposed a novel way to monitor river levels using inexpensive sensors powered by sunlight.','工程师提出一种利用廉价太阳能传感器监测河流水位的新方法。','The engineers proposed a novel way / to monitor river levels / using inexpensive sensors powered by sunlight.','novel 作形容词表示新颖、不同于既有做法。','太阳能廉价传感器是一种不同寻常的新方法。')],M('The engineers proposed a novel method that copied the standard design exactly and introduced no new approach.','The engineers proposed a novel method that used a new solar-powered sensor design.','完全照搬旧设计且没有新做法，不能称为 novel。','distinction'),[q('What does the novel’s young surveyor discover?','an old railway tunnel beneath the city','a new safety notice on a train','a garden lacking nourishment','小说情节中，测绘员发现地下旧隧道。'),q('Which proposal is novel in the adjective sense?','a new solar-powered method for measuring river levels','a method copied unchanged from an old manual','a familiar route used for centuries','形容词 novel 指新颖、不同于已有做法。',2,'meaning'),q('What is the novel in the first example?','a long fictional story','a sensor for measuring water','a short public announcement','句中 novel 作名词，指长篇虚构故事。',1,'meaning'),q('Which sentence uses novel as an adjective?','They tested a novel way to detect leaks.','She borrowed a novel from the library.','The novel described a surveyor.','第一句中 novel 修饰 way，表示新颖的。',2,'grammar')]);
P('novelist','Novelist combines novel with -ist and names an author who writes book-length fictional stories.',C('novelist.s1','小说家','The novelist spent three years researching coastal villages before setting her story there.','这位小说家在把故事设定于海滨村庄之前，花了三年时间进行调查。','The novelist spent three years researching coastal villages / before setting her story there.','novelist 指创作长篇虚构故事的作者。','长期调查为小说背景提供材料。'),M('The novelist wrote only a real-time weather table and no fictional story.','The novelist wrote a book-length fictional story based on her research.','novelist 指长篇小说作者，不是只编制天气表的人。','meaning'),[q('What did the novelist research?','coastal villages','nuclear power stations','a music notation system','她调查了海滨村庄。'),q('Which person is a novelist?','an author of long fictional stories','an editor who only checks tax forms','a reader who borrows one poem','novelist 指创作长篇虚构故事的作者。',1,'meaning'),q('How did the research help the story?','it informed the setting','it replaced the fictional plot with a weather chart','it made the book a legal notice','调查为小说背景提供资料。',1,'context'),q('What suffix appears in novelist?','-ist, naming a person associated with an activity','-less, meaning without','-ify, meaning to make','novelist 由 novel 加表示从业者的 -ist 构成。',1,'word-formation')]);
P('novelty','Novelty comes from novel and Latin novitas, “newness”; it can mean the quality of being new or an unusual new object.',[C('novelty.s1','新奇性','The novelty of the solar oven attracted visitors at first, but they kept using it because it worked reliably.','太阳能烤炉的新奇性起初吸引了访客，但它运行可靠，所以人们继续使用。','The novelty of the solar oven / attracted visitors at first / but they kept using it because it worked reliably.','novelty 可指事物新颖、不寻常的性质。','吸引访客的是它的新奇性，持续使用则因实用可靠。'),C('novelty.s2','新奇物品','At the fair, the children bought a small novelty that projected constellations onto the bedroom ceiling.','集市上，孩子们买了一件能把星座投到卧室天花板上的小玩意儿。','At the fair / the children bought a small novelty / that projected constellations onto the bedroom ceiling.','novelty 也可指新奇的小物品或玩意儿。','投影星座的小设备是新奇物品。')],M('The shop called the ordinary, long-used pencil a novelty because it was unchanged and completely familiar.','The shop called the newly invented star projector a novelty because it was unusual.','熟悉且长期使用的普通铅笔不是新奇物品。','meaning'),[q('What first attracted visitors to the solar oven?','its new and unusual quality','its low position in the room','the children’s constellation projector','novelty 在此指新颖性。'),q('What did the children buy at the fair?','a small constellation projector','a solar oven for the visitor center','a book of coastal village research','例句中的 novelty 是能投影星座的小物品。',2,'context'),q('Which sentence uses novelty to mean newness?','The novelty of the approach soon wore off.','She bought a novelty shaped like a tiny planet.','A novelist signed the book.','第一句中的 novelty 指新鲜感或新奇性。',1,'meaning'),q('What is a novelty in the object sense?','an unusual small item','the quality of being familiar','an author of long stories','novelty 也可指一件新奇的小物品。',2,'meaning')]);
P('November','November comes from Latin November, “ninth month,” from novem, “nine”; it is now the eleventh month of the year.',C('November.s1','十一月','The river survey is scheduled for November, after the autumn rains but before winter ice forms.','河流调查安排在十一月，秋雨之后、冬季结冰之前。','The river survey is scheduled for November / after the autumn rains / but before winter ice forms.','November 是公历一年中的第十一个月。','调查安排在秋末与冬季结冰之间。'),M('The museum announced that November is the month immediately after December.','The museum announced that November comes after October and before December.','November 位于 October 与 December 之间，不在 December 之后。','meaning'),[q('When is the river survey scheduled?','in November','in January','in July','调查安排在 November。'),q('Which month follows November?','December','October','February','November 后面是 December。',1,'context'),q('What does November’s Latin name originally refer to?','the ninth month','the eleventh month','the first month','November 的拉丁词源原指第九个月。',1,'word-formation'),q('Which event belongs to a particular November?','the town’s November festival','the word “river” in every language','the month of August in general','November’s event sense refers to activities in that month in a particular year. ',2,'meaning')]);
P('novice','Novice comes through Old French from Latin novicius, “new”; it names someone new to a job or activity and lacking experience.',C('novice.s1','新手；初学者','As a novice beekeeper, Omar practiced opening the hive with an experienced neighbor beside him.','作为养蜂新手，奥马尔在一位有经验的邻居陪同下练习打开蜂箱。','As a novice beekeeper / Omar practiced opening the hive / with an experienced neighbor beside him.','novice 指刚开始某项工作或活动、经验不足的人。','有经验的人在旁协助，说明奥马尔仍在学习。'),M('The novice pilot had flown commercial routes alone for twenty years and trained every new instructor.','The novice pilot had little experience and practiced under an instructor’s supervision.','有二十年经验并培训他人的飞行员不能称为 novice。','meaning'),[q('What was Omar learning to do?','open a beehive','repair a nuclear reactor','write a novel','他正在练习打开蜂箱。'),q('Who is a novice?','someone new to an activity with little experience','a veteran who trains every instructor','a person who has retired from every job','novice 指刚入门、经验不足的人。',1,'meaning'),q('Who stayed beside Omar as he practiced?','an experienced neighbor','a fairground vendor','a novelist','练习时有经验的邻居陪在旁边。',1,'context'),q('Which word is closest to novice here?','beginner','expert','spectator','novice 在此相当于 beginner。',1,'meaning')]);
P('now','Now comes from Old English nu; it can mean at the present time, immediately, as a transition for attention, or since a situation makes something relevant.',[C('now.s1','目前；现在','The archive is now open to researchers after the damaged roof was repaired.','屋顶修复后，档案馆目前已向研究人员开放。','The archive is now open / to researchers / after the damaged roof was repaired.','now 可表示目前这个时期。','修复完成后，档案馆当前的开放状态发生改变。'),C('now.s2','立刻；引起注意','“Now, step away from the wet paint,” the conservator said, pointing to the newly restored frame.','文物修复师指着刚修好的画框说：“现在，请离湿漆远一点。”','“Now, step away from the wet paint,” / the conservator said / pointing to the newly restored frame.','now 可表示立刻行动，也可用于引起听者注意。','now 引出即时指令。'),C('now.s3','既然；由于','Now that the flood warning has ended, the crew can reopen the riverside path.','既然洪水警报已经解除，工作人员就可以重新开放河边步道。','Now that the flood warning has ended / the crew can reopen / the riverside path.','now 可见于 now that 从句，表示“既然、由于”。','警报解除是重新开放步道的原因。'),C('now.s4','此刻','The clock struck noon, and the guide asked everyone to pause and listen to the bells now.','钟敲响正午，导览员请大家此刻停下脚步听钟声。','The clock struck noon / and the guide asked everyone / to listen to the bells now.','now 也可强调当前这一具体时刻。','导览员要求大家此刻聆听钟声。')],M('Now that the flood warning had ended, the crew refused to reopen the path because the warning was still active.','Now that the flood warning had ended, the crew reopened the path.','警报已解除与仍处于警报状态相矛盾。','meaning'),[q('What is the archive’s current status?','it is open to researchers','its roof is still damaged','it is closing for winter','now 在句中表示档案馆目前的状态。'),q('What did the conservator order immediately?','step away from the wet paint','listen to a noon bell tomorrow','reopen the river path','引语中的 now 引出立刻执行的指令。',2,'context'),q('Why can the crew reopen the path?','the flood warning has ended','the archive has opened','the bells struck noon','now that 从句给出重新开放的原因。',3,'meaning'),q('Which use points to this exact moment?','Listen to the bells now.','The archive is now open this month.','Now that the warning ended, work resumed.','第一句的 now 强调此刻。',4,'meaning')]);
P('now and then','Now and then is a fixed phrase meaning sometimes, but not often; it describes an occasional event.',C('now and then.s1','偶尔；时常','Now and then, the retired pilot visits the airfield to tell the trainees about his first flight.','那位退休飞行员偶尔会去机场，给学员讲述自己的首次飞行经历。','Now and then / the retired pilot visits the airfield / to tell the trainees about his first flight.','now and then 是频率副词短语，表示不时、偶尔。','退休飞行员并非天天去，而是偶尔探访。'),M('The retired pilot visits the airfield every morning without a single day away, so he goes there only now and then.','The retired pilot visits the airfield every morning, so he goes there regularly rather than only now and then.','每天都去与“偶尔去”频率相反。','meaning'),[q('How often does the retired pilot visit?','occasionally','every single morning','only once in his entire life','now and then 表示偶尔，不是每天。'),q('Which schedule fits now and then?','checking the telescope on a few scattered evenings','checking it every hour without a break','never checking it at all','零星的几个晚上符合“偶尔”。',1,'meaning'),q('Why does the pilot visit the airfield?','to tell trainees about his first flight','to repair a wet picture frame','to collect the monthly rent','他去机场给学员讲首次飞行经历。',1,'context'),q('Which phrase is closest in meaning to now and then?','occasionally','continuously','at once','now and then 相当于 occasionally。',1,'meaning')]);
P('nowadays','Nowadays combines now with days and means in the present period, especially when contrasting current life with the past.',[C('nowadays.s1','如今；与过去对比','People nowadays can check a river gauge online, whereas the old surveyors had to travel to each station.','如今人们可以在线查看河流水位计，而过去的测绘人员必须逐个前往测站。','People nowadays can check a river gauge online / whereas the old surveyors / had to travel to each station.','nowadays 常用于对比今昔的生活或条件。','句子对比在线查看与过去逐站出行。'),C('nowadays.s2','在现代','Many archives nowadays preserve fragile maps in climate-controlled rooms rather than open display cases.','如今许多档案馆会把易损地图保存在恒温房间里，而不是放在开放展柜中。','Many archives nowadays preserve fragile maps / in climate-controlled rooms / rather than open display cases.','nowadays 也可概括现代时期的普遍情况。','句子描述现代档案馆的保存方式。')],M('Nowadays, surveyors must visit every gauge in person because online readings are widely available and no one uses them.','Nowadays, surveyors can check many gauge readings online instead of visiting every station.','普遍可用的在线读数让“必须逐站到访”这个断言不成立。','meaning'),[q('How can people check river gauges nowadays?','online','only by traveling to every station','by reading a nineteenth-century novel','句子说如今可在线查看水位计。'),q('How do many modern archives protect fragile maps?','in climate-controlled rooms','in open cases under direct sunlight','inside the river gauge','如今许多档案馆使用恒温房间保存易损地图。',2,'context'),q('Which sentence contrasts the present with the past?','Nowadays we use digital maps; earlier travelers relied on paper charts.','A novice opened the map once.','The map is nowhere to be found.','nowadays 常用于今昔对比。',1,'meaning'),q('Nowadays most nearly means?','in the present period','at one exact second only','at some time in the distant future','nowadays 指目前这个时期。',1,'meaning')]);
P('nowhere','Nowhere combines no and where and means in no place; in phrases like get nowhere, it means make no progress.',[C('nowhere.s1','无处；任何地方都不','The field team searched the eastern bank, but the missing sample container was nowhere in the marked area.','野外小组搜索了东岸，但标记区域里哪里都找不到丢失的样本容器。','The field team searched the eastern bank / but the missing sample container was nowhere / in the marked area.','nowhere 可表示某物不在任何地点。','搜遍标记区域仍未找到样本容器。'),C('nowhere.s2','毫无进展','After three hours of arguing over the budget, the committee was getting nowhere and postponed the decision.','委员会为预算争论了三小时仍毫无进展，便推迟了决定。','After three hours of arguing over the budget / the committee was getting nowhere / and postponed the decision.','get nowhere 是固定说法，表示毫无进展或未达成结果。','争论没有解决问题，所以决定延期。')],M('The team found the container nowhere in the marked area, and it was sitting plainly beside the eastern gate.','The team found the container nowhere in the marked area, so it continued searching beyond the eastern gate.','如果容器明明在标记区域内，就不能说该区域任何地方都没有。','meaning'),[q('Where was the missing container?','it was in no place in the marked area','it was clearly beside the eastern gate','it was already in the laboratory fridge','例句说标记区域内任何地方都没有容器。'),q('Why did the committee postpone its decision?','it made no progress on the budget','it had agreed on every budget item','it lost a sample container','get nowhere 表示委员会讨论毫无进展。',2,'context'),q('Which sentence uses nowhere to mean no progress?','We argued for hours and got nowhere.','The keys are nowhere in this drawer.','The train stopped nowhere today.','argued for hours and got nowhere 表示争论没有进展。',2,'meaning'),q('In the first example, nowhere most nearly means?','not in any place','at every station','on the eastern bank for certain','nowhere 表示不在任何地方。',1,'meaning')]);
P('noxious','Noxious comes from Latin noxius, “harmful,” related to nocere, “to injure”; it describes something harmful or poisonous, including morally corrupting material.',[C('noxious.s1','有害的；有毒的','Workers evacuated the greenhouse after a noxious gas escaped from a cracked storage cylinder.','储气罐开裂并泄漏有毒气体后，工人撤离了温室。','Workers evacuated the greenhouse / after a noxious gas escaped / from a cracked storage cylinder.','noxious 作形容词表示对人或环境有害的。','气体泄漏会伤害工人，因此需要撤离。'),C('noxious.s2','败坏道德的','The essay warned that noxious propaganda can encourage hatred toward an entire community.','这篇文章警告，有害的宣传可能煽动对整个群体的仇恨。','The essay warned / that noxious propaganda / can encourage hatred toward an entire community.','noxious 也可比喻描述会损害道德或价值观的内容。','仇恨宣传对社会价值观造成危害。')],M('The noxious gas was harmless to the workers, so the safety team left the leak uncontained.','The noxious gas could harm workers, so the safety team evacuated the greenhouse.','noxious 表示有害，不能据此说气体无害。','meaning'),[q('Why did workers leave the greenhouse?','a harmful gas escaped','a novelist entered the building','the river gauge stopped','noxious gas 泄漏会危害工作人员。'),q('What harm can noxious propaganda cause?','it can encourage hatred toward a community','it can improve a cracked cylinder','it can nourish seedlings','例句指出宣传可能煽动仇恨。',2,'context'),q('Which substance is noxious in the physical sense?','a poisonous vapor leaking from a tank','clean air from an open window','water with no harmful chemicals','有毒蒸气属于物理意义上的有害物质。',1,'meaning'),q('What does noxious mean in the essay’s figurative use?','morally damaging','pleasantly nourishing','easy to notice','比喻用法描述败坏道德或价值观的内容。',2,'meaning')]);
P('nozzle','Nozzle is an English word of uncertain origin; it names a projecting spout that directs liquid, gas, or another flow.',C('nozzle.s1','喷嘴；管嘴','The mechanic replaced the cracked nozzle so the hose would send a narrow stream into the irrigation channel.','机械师更换了开裂的喷嘴，让软管把一股细水流送进灌溉渠。','The mechanic replaced the cracked nozzle / so the hose would send a narrow stream / into the irrigation channel.','nozzle 是管子或软管前端引导流体的突出口。','更换喷嘴后，水流被集中导向渠道。'),M('The hose directed its stream through a missing nozzle that had no opening or projecting spout.','The hose directed its stream through a nozzle with an opening that shaped the flow.','没有开口或突出口的部件不能作为引导水流的喷嘴。','meaning'),[q('What did the mechanic replace?','a cracked nozzle','the whole irrigation channel','a river survey notebook','机械师更换了开裂的喷嘴。'),q('What does a nozzle do?','directs or shapes a flow from a pipe','records a musical rhythm','measures the depth of a river','喷嘴从管道出口引导或塑造流体。',1,'meaning'),q('Where was the water sent after the repair?','into the irrigation channel','onto the archive’s map','into the fuel tank','细水流被送进灌溉渠。',1,'context'),q('What is known about nozzle’s origin here?','its origin is uncertain','it is certainly Latin for “river”','it was formed from note plus book','现有词源资料不能确定 nozzle 的起源。',1,'word-formation')]);
P('nuance','Nuance was borrowed from French nuance, “a shade or subtle gradation,” and means a small difference in meaning, sound, color, or feeling.',C('nuance.s1','细微差别','The translator preserved the nuance between “concerned” and “alarmed” so the speaker sounded cautious rather than frightened.','译者保留了“担忧”和“惊慌”之间的细微差别，使说话者听起来是谨慎而非害怕。','The translator preserved the nuance / between “concerned” and “alarmed” / so the speaker sounded cautious rather than frightened.','nuance 指词义、语气或感受中的细微差别。','两个近义词的情绪强度不同。'),M('The translator treated “concerned” and “alarmed” as having exactly the same nuance and emotional force.','The translator preserved the different nuance and emotional force of “concerned” and “alarmed.”','这两个词的情绪强度并不完全相同，译文应保留其差异。','distinction'),[q('Which distinction did the translator preserve?','concerned sounds less intense than alarmed','both words mean “not anywhere”','one word names a type of nozzle','例句对比“担忧”与“惊慌”的强度。'),q('Where can a nuance occur?','in the slight difference between two shades of meaning','only in a large numerical difference','only in a printed public notice','nuance 指细微而非巨大的差异。',1,'meaning'),q('What effect did the careful translation create?','the speaker sounded cautious, not frightened','the speaker sounded certain that nothing happened','the speaker’s words became a legal notice','译者让说话者显得谨慎而非惊恐。',1,'context'),q('The French source nuance originally refers to?','a shade or subtle gradation','a central atomic particle','a sudden physical nudge','法语 nuance 有“色调、细微层次”之意。',1,'word-formation')]);
P('nuclear','Nuclear is formed from nucleus plus -ar; it can relate to atomic nuclei or nuclear energy, and can describe a central cell or family unit.',[C('nuclear.s1','原子核的；核能的','The laboratory measured nuclear reactions in the sample while following strict radiation-safety rules.','实验室在严格遵守辐射安全规定的同时，测量样本中的核反应。','The laboratory measured nuclear reactions / in the sample / while following strict radiation-safety rules.','nuclear 作形容词可指原子核或由核反应产生的能量。','辐射安全要求与核反应实验相符。'),C('nuclear.s2','核心的；中心的','In the cell diagram, the nuclear membrane surrounds the central compartment that contains the genetic material.','细胞示意图中，核膜围绕着含有遗传物质的中央区域。','In the cell diagram / the nuclear membrane surrounds the central compartment / that contains the genetic material.','nuclear 也可指细胞核或家庭等结构中的中心部分。','核膜包围含遗传物质的细胞中心区域。')],M('The nuclear membrane surrounded the outermost edge of the cell and excluded the central genetic material.','The nuclear membrane surrounded the central compartment containing genetic material.','nuclear membrane 围绕细胞核，而不是与核内遗传物质完全分离的外围。','meaning'),[q('What did the laboratory measure?','nuclear reactions','a nuance in a poem','a nozzle’s water stream','实验室测量的是核反应。'),q('What does the nuclear membrane surround in the diagram?','the cell’s central compartment','the outside of the greenhouse','the river bank','核膜围绕细胞中央区域。',2,'context'),q('Which phrase uses nuclear in the atomic sense?','nuclear energy from a reactor','a nuclear family living in one home','the nucleus of a cell','reactor 产生的能量是原子核反应相关的。',1,'meaning'),q('Which is a central or core use of nuclear?','the nuclear membrane of a cell','a nuclear weapon system','a nuclear power plant','细胞核膜体现“中心部分”的相关用法。',2,'meaning')]);
P('nucleic','Nucleic is formed from nucleus plus -ic and means relating to nucleic acids such as DNA and RNA, which carry genetic information.',C('nucleic.s1','核酸的','The biology class compared nucleic acid samples to see how DNA and RNA store or transmit genetic information.','生物课比较了核酸样本，研究 DNA 和 RNA 如何储存或传递遗传信息。','The biology class compared nucleic acid samples / to see how DNA and RNA / store or transmit genetic information.','nucleic 常见于 nucleic acid，表示与 DNA、RNA 等核酸有关。','比较对象是携带遗传信息的核酸。'),M('The report called the genetic material nucleic acid even though it contained no DNA or RNA and carried no genetic information.','The report called the DNA and RNA samples nucleic acids because they carry genetic information.','DNA 和 RNA 是核酸；不含二者且不传遗传信息的物质不符合此处定义。','meaning'),[q('Which molecules did the class compare?','DNA and RNA','proteins used only for muscle movement','water in the irrigation hose','DNA 和 RNA 是例句中的核酸样本。'),q('What does nucleic describe?','something related to DNA or RNA acids','something relating to a water nozzle','something famous for a bad reason','nucleic 表示核酸相关的。',1,'meaning'),q('What do nucleic acids carry?','genetic information','a narrow stream of water','a formal advance warning','例句说 DNA 和 RNA 储存或传递遗传信息。',1,'context'),q('Which phrase is the common scientific collocation?','nucleic acid','nucleic novelist','nucleic nuance','nucleic 最常见的搭配是 nucleic acid。',1,'collocation')]);
P('nucleus','Nucleus comes from Latin nucleus, “kernel,” from nux, “nut”; it names the center of an atom or cell, and by extension the core of a group.',[C('nucleus.s1','原子核','The diagram showed electrons around a tiny nucleus at the center of each atom.','示意图显示，每个原子中心的微小原子核周围有电子。','The diagram showed electrons / around a tiny nucleus / at the center of each atom.','nucleus 可指原子的中心部分，即原子核。','图示明确区分原子中心与外围电子。'),C('nucleus.s2','细胞核','Under the microscope, the stain made the nucleus of each cell visible.','在显微镜下，染色使每个细胞的细胞核都清晰可见。','Under the microscope / the stain made the nucleus / of each cell visible.','nucleus 也可指细胞中含遗传物质的中央部分。','显微镜下观察的是细胞结构。'),C('nucleus.s3','核心；中心群体','A small group of volunteers formed the nucleus of the flood-response team before more neighbors joined.','更多邻居加入前，一小群志愿者构成了洪灾应对团队的核心。','A small group of volunteers / formed the nucleus of the flood-response team / before more neighbors joined.','nucleus 可比喻指团体或事物最核心的部分。','最初的小组是后来扩大团队的核心。')],M('The nucleus of the cell was the outer boundary far from its genetic material.','The nucleus was the cell’s central compartment containing its genetic material.','细胞核位于细胞内部中心，并含有遗传物质，不是外边界。','meaning'),[q('What lies at the center of each atom in the diagram?','a tiny nucleus','a volunteer group','a stained slide','原子中心是微小的原子核。'),q('What did the stain make visible?','the nucleus of each cell','the volunteers’ flood-response plan','the electrons in a river','染色使细胞核清晰可见。',2,'context'),q('What formed the nucleus of the response team?','a small group of volunteers','the whole town after everyone joined','the river’s outer bank','最初的小群体构成了团队核心。',3,'meaning'),q('Which use means the central part of a cell?','the cell nucleus','the nucleus of a volunteer team','the nucleus of an atom','第二项是团体核心；第一项明确指细胞核。',2,'distinction')]);
P('nude','Nude comes from Latin nudus, “bare,” through French; it can describe a person without clothes or a work of art showing an unclothed figure.',[C('nude.s1','裸体的','The life-drawing class used a draped model instead of a nude figure during the introductory session.','人体写生入门课使用了披着布料的模特，而不是裸体模特。','The life-drawing class used a draped model / instead of a nude figure / during the introductory session.','nude 作形容词描述未穿衣服的人或形象。','句子将披布模特与裸体形象作对比。'),C('nude.s2','裸体人像作品','The gallery moved a nineteenth-century nude to a quieter room so visitors could view the painting without crowding.','画廊把一幅十九世纪裸体人像画移到较安静的展厅，让观众不必拥挤地欣赏。','The gallery moved a nineteenth-century nude / to a quieter room / so visitors could view the painting without crowding.','nude 也可作名词指裸体人物的绘画、照片或雕塑。','句中 nude 是被移动的一幅画作。')],M('The gallery described the clothed portrait as a nude even though the subject wore a full winter coat.','The gallery described the unclothed figure in the painting as a nude.','穿着完整冬衣的人像不符合裸体人像作品的含义。','meaning'),[q('What did the introductory class use?','a draped model','a nude figure','a sculpture of a nozzle','入门课程使用披布模特。'),q('What did the gallery move?','a nineteenth-century painting of an unclothed figure','a winter coat from the storeroom','a life-drawing notebook','这里名词 nude 指裸体人像画。',2,'context'),q('Which sentence uses nude as an adjective?','The artist sketched a nude model.','The gallery displayed a nude.','They moved the nude to another room.','第一句中 nude 修饰 model，作形容词。',1,'grammar'),q('Which sentence uses nude as a noun for an artwork?','The museum acquired a nude by a nineteenth-century painter.','The model was nude for the sketch.','The visitor wore nude-colored shoes.','第一句中 nude 指一件裸体人物艺术作品。',2,'meaning')]);
P('nudge','Nudge is an English word whose origin is uncertain; it means to push someone gently or to prompt them to act.',C('nudge.s1','轻推；劝促','Mara nudged her colleague gently when the speaker called his name and he did not hear it.','演讲者叫到同事名字而他没听见时，玛拉轻轻推了推他。','Mara nudged her colleague gently / when the speaker called his name / and he did not hear it.','nudge 作动词可指轻推，也可比喻为温和地促使某人行动。','轻推提醒同事注意正在发生的事。'),M('Mara nudged her colleague by shoving him across the room with great force.','Mara nudged her colleague with a gentle push to get his attention.','nudge 指轻柔的小推，不是用很大力气把人推过房间。','meaning'),[q('Why did Mara nudge her colleague?','he did not hear the speaker call his name','he had already left the room','he was asleep at home','同事没听到自己的名字，玛拉轻推提醒他。'),q('Which action is a nudge?','a gentle tap to prompt someone to look up','a violent shove that knocks someone down','a written notice posted on a door','nudge 是轻推或温和提醒。',1,'meaning'),q('Which example is figurative?','A reminder nudged her to submit the form.','He nudged the door open with his shoulder.','The water flowed through a nozzle.','提醒“促使”她提交表格，是比喻的劝促义。',1,'distinction'),q('What is known about the word’s origin in the available source?','it is uncertain','it certainly comes from the Latin word for nut','it is formed from note and book','现有资料将 nudge 的词源列为不确定。',1,'word-formation')]);
P('nuisance','Nuisance comes through Old French from nuire, “to harm”; it means an annoying problem or, in law, an unlawful interference with land use.',[C('nuisance.s1','麻烦；讨厌的事','The broken alarm became a nuisance because it rang every night even after the building was empty.','警报器每晚都会响，即使楼里没人也不停，因此成了令人烦恼的麻烦。','The broken alarm became a nuisance / because it rang every night / even after the building was empty.','nuisance 可指持续烦人的人或事。','反复夜间响铃造成困扰。'),C('nuisance.s2','法律上的妨害','The court ruled that the factory’s smoke was a nuisance because it repeatedly prevented residents from enjoying their gardens.','法院裁定工厂烟雾构成妨害，因为它屡次妨碍居民使用花园。','The court ruled that the factory’s smoke was a nuisance / because it repeatedly prevented residents / from enjoying their gardens.','法律语境中 nuisance 指非法干扰他人使用和享受土地。','烟雾影响居民使用自家花园。')],M('The alarm was a nuisance because it never rang, disturbed nobody, and caused no inconvenience.','The alarm was a nuisance because its repeated nighttime ringing disturbed nearby residents.','从不响且无人受扰的警报不构成此处所说的麻烦。','meaning'),[q('Why was the alarm a nuisance?','it rang repeatedly at night','it was silent in an empty room','it measured the cell nucleus','反复夜间响铃使警报器很烦人。'),q('Why did the court call the factory smoke a nuisance?','it interfered with residents’ use of their gardens','it helped residents grow vegetables','it stopped the alarm from ringing','烟雾妨碍居民享受花园，构成法律上的妨害。',2,'context'),q('Which situation is a nuisance in the everyday sense?','a broken light that flashes all night','a quiet lamp that works normally','a map that is easy to read','持续造成不便的闪灯是麻烦。',1,'meaning'),q('In property law, nuisance concerns?','unlawful interference with another person’s use of land','a person new to a job','a group’s central members','法律上的 nuisance 涉及妨碍他人使用土地。',2,'meaning')]);
P('null','Null comes from Latin nullus, “none”; it means having no value or legal force, often in computing or formal documents.',C('null.s1','空值；无效的','The database returned a null value for the delivery date because no date had been entered.','由于没有输入日期，数据库为送货日期字段返回了空值。','The database returned a null value / for the delivery date / because no date had been entered.','null 在数据语境中表示没有可用数值，也可指法律上无效。','日期未录入，所以字段为空。'),M('The database stored a null delivery date and displayed it as a confirmed date of 12 June.','The database stored a null delivery date because no confirmed date had been entered.','null 表示没有值，不能同时当成已经确认的日期。','meaning'),[q('Why did the database return a null date?','no delivery date had been entered','the delivery was confirmed for 12 June','the database had printed a notice','字段未录入日期，因此返回空值。'),q('Which record is null?','a field containing no value','a field containing a confirmed address','a signed contract with legal force','null 表示字段没有值。',1,'meaning'),q('Which action can make a contract null?','a court declares it legally invalid','a clerk enters a valid date','a reader notices its title','法律意义的 null 可表示无效。',1,'distinction'),q('What does Latin nullus mean?','none','new','to feed','nullus 是“没有、无”的意思。',1,'word-formation')]);
P('nullify','Nullify combines null with -ify and means to make something legally void or to cancel its effect.',C('nullify.s1','使无效；抵消','The court nullified the agreement after finding that one required signature had been forged.','法院发现一处必要签名系伪造后，宣布协议无效。','The court nullified the agreement / after finding / that one required signature had been forged.','nullify 是及物动词，表示使某事失去法律效力或抵消其作用。','伪造签名导致协议被作废。'),M('The court nullified the forged contract by confirming that it remained fully valid and enforceable.','The court nullified the forged contract by declaring that it was no longer valid.','宣布协议仍完全有效与使其无效相反。','meaning'),[q('Why did the court nullify the agreement?','a required signature had been forged','all parties had signed it correctly','the agreement was stored in a database','签名伪造是法院宣布协议无效的理由。'),q('Which action would nullify a rule?','repealing it so that it has no force','printing it clearly on a notice','measuring it with a ruler','nullify 指使规则失效或抵消其效力。',1,'meaning'),q('What became invalid in the example?','the agreement','the court building','the delivery date field','被宣布无效的是协议。',1,'context'),q('What does -ify contribute to nullify?','the verb-forming idea “make or render”','the plural form of noun','the meaning “in no place”','-ify 构成表示“使成为”的动词。',1,'word-formation')]);
P('numb','Numb comes from Old English niman, “to take,” with a historical sense of being deprived of sensation; it can describe bodily or emotional insensibility, or the act of causing it.',[C('numb.s1','身体麻木','After sitting in the cold boat, Jun’s fingers were numb and he struggled to fasten the safety buckle.','在冰冷的船上坐了一会儿后，君的手指冻得麻木，难以扣上安全带。','After sitting in the cold boat / Jun’s fingers were numb / and he struggled to fasten the safety buckle.','numb 作形容词可指身体某部位失去感觉。','冻僵的手指难以完成精细动作。'),C('numb.s2','情感麻木','After the long emergency shift, the nurse felt numb and could not react to another alarm for several minutes.','长时间值完急诊班后，护士感到情感麻木，几分钟内对另一声警报都难以作出反应。','After the long emergency shift / the nurse felt numb / and could not react to another alarm for several minutes.','numb 也可形容因震惊或悲伤而暂时失去情感反应。','长时间紧张工作后出现情绪麻木。'),C('numb.s3','使麻木','The dentist used a local anesthetic to numb the area around the patient’s tooth before treatment.','治疗前，牙医使用局部麻醉剂使患者牙齿周围区域麻木。','The dentist used a local anesthetic / to numb the area around the patient’s tooth / before treatment.','numb 还可作动词，表示使身体或情感失去感觉。','局部麻醉让治疗部位暂时失去痛觉。')],M('The anesthetic numbed the patient’s tooth by making the area more sensitive to pain.','The anesthetic numbed the area by reducing its ability to feel pain.','麻醉使感觉减弱，不会让该部位对疼痛更敏感。','meaning'),[q('Why could Jun not fasten the buckle easily?','his fingers had lost sensation in the cold','his safety belt was a nuisance','he had a null delivery date','寒冷使手指麻木，影响扣带。'),q('How did the nurse feel after the emergency shift?','emotionally unresponsive for a while','physically unable to move her fingers','excited to hear another alarm','护士感到情感麻木，暂时难以回应。',2,'context'),q('What did the dentist do to the area near the tooth?','made it temporarily unable to feel pain','made it more sensitive to pain','removed the patient’s whole tooth','动词 numb 表示使治疗区域麻木。',3,'meaning'),q('Which sentence uses numb figuratively?','Shock left him numb after the accident.','The cold water made her hand numb.','The anesthetic will numb the gum.','事故后的震惊导致情感麻木，是比喻用法。',2,'distinction')]);
P('number','Number comes through Old French from Latin numerus, “number”; it can be a figure or quantity, an issue or show item, or the act of assigning or totaling.',[C('number.s1','数字；号码','Write the locker number on the entry form so the attendant can match each key to its owner.','请在登记表上写下储物柜号码，以便管理员把每把钥匙对应到柜主。','Write the locker number / on the entry form / so the attendant can match each key to its owner.','number 可指表示数量、顺序或身份的数字或编号。','编号用于识别储物柜。'),C('number.s2','数量；数目','A large number of volunteers arrived before dawn to help restore the riverbank.','天亮前就有大量志愿者赶来帮助修复河岸。','A large number of volunteers arrived / before dawn / to help restore the riverbank.','a number of + 复数名词表示一定数量的人或物。','许多志愿者参与河岸修复。'),C('number.s3','一期；节目项目','The final number in the concert was a chorus performed by the entire school.','音乐会的最后一个节目是全校合唱。','The final number in the concert / was a chorus / performed by the entire school.','number 可指杂志的一期或演出中的一个节目。','演出顺序中最后一个项目是合唱。'),C('number.s4','编号；总计','The clerk numbered the sample bottles, and the labels number forty-eight in total.','职员给样品瓶编号，标签总计四十八张。','The clerk numbered the sample bottles / and the labels number forty-eight / in total.','number 可作动词，表示给物品编号或总计为某数。','句中前一个 number 是编号，后一个表示总数。')],M('The clerk numbered each bottle but left every bottle without an identifying number.','The clerk numbered each bottle with a distinct identifying number.','给物品编号意味着为其标上编号，不能说编号后仍没有任何识别号码。','meaning'),[q('What should be written on the entry form?','the locker’s identifying number','the volunteer’s lunch order','the concert’s final chorus','登记表需要储物柜编号。'),q('How many volunteers arrived before dawn?','a large number','exactly one','none at all','a large number 表示人数很多。',2,'meaning'),q('What was the concert’s final number?','a chorus performed by the school','the locker number','a list of sample bottles','number 在演出语境中指节目项目。',3,'context'),q('What does the clerk do when she numbers bottles?','assigns an identifying figure to each one','counts how many concerts were held','writes a song for the final act','动词 number 可表示给物品编号。',4,'meaning')]);
P('numeral','Numeral comes from Latin numeralis, “relating to number,” and names a word or symbol used to express a number.',C('numeral.s1','数字符号','The Roman numeral IX appears above the doorway to show that the hall was built in the ninth century.','门上方的罗马数字 IX 表示这座大厅建于九世纪。','The Roman numeral IX appears above the doorway / to show / that the hall was built in the ninth century.','numeral 指表示数值的数字词或符号。','IX 是代表九的罗马数字符号。'),M('The inscription used the Roman numeral IX to show that the hall was built in the seventh century.','The inscription used the Roman numeral VII to show that the hall was built in the seventh century.','IX 表示九，VII 才表示七。','meaning'),[q('Which numeral appears above the doorway?','IX','XI','IV','门上方出现的是 IX。'),q('What does IX represent in Roman numerals?','nine','seven','eleven','IX 表示九。',1,'meaning'),q('What does the numeral tell visitors about the hall?','it was built in the ninth century','it contains nine doorways','it has eleven rooms','IX 用来表示大厅建于九世纪。',1,'context'),q('A numeral is a word or symbol used to express?','a number','a legal nuisance','a kind of nurse','numeral 表示用于表达数字的词或符号。',1,'meaning')]);
P('numerate','Numerate comes from Latin numerare, “to count,” and means to number or list items in order.',C('numerate.s1','编号；列举','Before the raffle, the organizer asked two volunteers to numerate the tickets from one to five hundred.','抽奖前，组织者请两名志愿者把抽奖券从一到五百依次编号。','Before the raffle / the organizer asked two volunteers / to numerate the tickets from one to five hundred.','numerate 作动词表示按顺序给物品编号或列举。','抽奖券需要依次编号以便抽取。'),M('The volunteers numerated the raffle tickets by leaving every ticket unnumbered and mixed together.','The volunteers numerated the raffle tickets by numbering them in order.','numerate tickets 意味着编号，完全不编号与动作含义相反。','meaning'),[q('What did the volunteers numerate?','raffle tickets','river gauges','a Roman doorway','志愿者为抽奖券编号。'),q('Which task is to numerate items?','labeling a set of forms 1, 2, 3, and 4','writing a story with no sequence','removing all labels from a box','按顺序标号就是 numerate。',1,'meaning'),q('Why should the tickets be numbered?','so the raffle entries can be identified in order','so the volunteers can change the prize','so each ticket becomes a novel','有顺序的编号便于识别和抽取抽奖券。',1,'context'),q('Which Latin verb is related to numerate?','numerare, “to count”','nutrire, “to feed”','noscere, “to know”','numerate 与表示计数的拉丁语 numerare 有关。',1,'word-formation')]);
P('numerator','Numerator comes from Latin numerator, “one who counts,” and in a fraction a/b is the number a showing how many parts are taken.',C('numerator.s1','分子','In the fraction three-quarters, 3 is the numerator because it counts the parts being considered.','在四分之三这个分数中，3 是分子，因为它表示所取的部分数。','In the fraction three-quarters / 3 is the numerator / because it counts the parts being considered.','分数中，分子位于分数线上方，表示取了多少份。','3/4 中取了三份，所以 3 是分子。'),M('In the fraction 3/4, the numerator is 4 because it appears above the fraction bar.','In the fraction 3/4, the numerator is 3 because it appears above the fraction bar.','分数线上的数 3 是分子；下方的 4 是分母。','meaning'),[q('What is the numerator in three-quarters?','3','4','7','四分之三中分子是 3。'),q('Where is a fraction’s numerator written?','above the fraction bar','below the fraction bar','beside the equals sign only','分子写在分数线的上方。',1,'context'),q('In 5/8, which number is the numerator?','5','8','13','5/8 中分子是 5。',1,'meaning'),q('What does the numerator count in the example?','the parts being taken','the total number of equal groups only','the number of fraction bars','分子表示所取的部分数。',1,'meaning')]);
P('numeric','Numeric combines number with -ic and means having to do with numbers or a system of numbers.',C('numeric.s1','数字的；数值的','The numeric keypad lets the cashier enter the invoice total without reaching across the whole keyboard.','数字键盘让收银员无需伸手越过整个键盘就能输入发票总额。','The numeric keypad lets the cashier enter the invoice total / without reaching across / the whole keyboard.','numeric 作形容词，表示与数字或数值有关。','键盘区用于输入数字金额。'),M('The numeric keypad contained only painted flowers and no number keys.','The numeric keypad contained number keys for entering amounts.','没有数字键的键盘区不能称为 numeric keypad。','meaning'),[q('What does the cashier enter with the numeric keypad?','the invoice total','the customer’s name in cursive','a musical rhythm','数字键盘用于输入发票总额。'),q('Which item is numeric data?','the value 407 in a measurement column','a descriptive note saying “very cold”','a sketch of a river bank','407 是数值数据。',1,'meaning'),q('What is the keypad designed to help with?','entering number values quickly','writing long fictional stories','playing a final concert number','数字键盘便于输入数字。',1,'context'),q('Numeric most nearly means?','related to numbers','related to nursing','well known for a bad reason','numeric 表示与数字有关。',1,'meaning')]);
P('numerical','Numerical is formed from number plus -ical; it means relating to numbers or expressed with figures rather than words.',[C('numerical.s1','数值相关的','The analyst compared numerical results from three river gauges before drawing a conclusion about the flood risk.','分析人员先比较了三个河流水位计的数值结果，再判断洪水风险。','The analyst compared numerical results / from three river gauges / before drawing a conclusion about the flood risk.','numerical 可表示与数字计算或数值有关。','比较仪器读数属于数值分析。'),C('numerical.s2','用数字表达的','Please give your numerical answer as 12, not by spelling out the word twelve.','请把答案用数字写成 12，不要拼写成 twelve。','Please give your numerical answer as 12 / not by spelling out / the word twelve.','numerical 也可指用数字符号而非文字表示的。','要求用数字 12 作答。')],M('The instructions asked for a numerical answer, but the student wrote only the word “twelve” in letters.','The instructions asked for a numerical answer, so the student wrote “12” in figures.','numerical answer 要用数字表示，拼写成文字不符合要求。','distinction'),[q('What did the analyst compare?','figures from three river gauges','three fictional novels','the color of three maps','分析人员比较了三个水位计的数值。'),q('How should the student write the requested answer?','as the figure 12','as the word “twelve” only','as a Roman numeral IX','题目要求用数字形式写 12。',2,'context'),q('Which item is numerical data?','a recorded value of 8.6 meters','the phrase “the river looks high”','a hand-drawn picture of a gauge','8.6 米是用数字表示的数据。',1,'meaning'),q('What does numerical mean in “numerical results”?','relating to numbers or measurements','relating only to written descriptions','relating to a nursery','数值结果与数字或测量有关。',1,'meaning')]);
P('numerous','Numerous comes from Latin numerosus, “full of number,” and means very many or made up of a large number of people or things.',[C('numerous.s1','许多的','Numerous small streams feed the lake after several days of spring rain.','春雨连续下了几天后，许多小溪汇入湖中。','Numerous small streams feed the lake / after several days / of spring rain.','numerous 作形容词表示数量很多，后接可数名词复数。','多条小溪在春雨后汇入湖泊。'),C('numerous.s2','人数众多的','The panel was numerous enough to include engineers, residents, and wildlife experts from every district.','委员会人数众多，囊括了各区的工程师、居民和野生动物专家。','The panel was numerous enough / to include engineers, residents, and wildlife experts / from every district.','numerous 也可强调一个群体由很多成员组成。','委员会包含多个地区的不同成员。')],M('Numerous stream flowed into the lake after the rain.','Numerous streams flowed into the lake after the rain.','numerous 后接可数名词复数 streams。','plural'),[q('What feeds the lake after spring rain?','many small streams','one dry field','a single paper notice','许多小溪汇入湖中。'),q('Who made up the numerous panel?','engineers, residents, and wildlife experts','one person from a single district','only the lake’s fish','委员会成员来自不同领域和地区，人数众多。',2,'context'),q('Which noun form follows numerous?','numerous volunteers','numerous volunteer','numerous much volunteer','numerous 修饰可数名词复数。',1,'grammar'),q('What does numerous mean?','very many','exactly one','having no value','numerous 表示很多。',1,'meaning')]);
P('nun','Nun comes from Old English nunne, from Latin nonna, and names a woman who belongs to a religious community and has taken vows.',C('nun.s1','修女','The nun tended the community garden and taught the children to identify herbs used in the kitchen.','修女照料社区花园，并教孩子们辨认厨房会用到的香草。','The nun tended the community garden / and taught the children / to identify herbs used in the kitchen.','nun 指加入宗教团体并立誓的女性成员。','例句中的人物参与社区生活和教学。'),M('The nun joined the religious community but took no vows and was not a member of it.','The nun joined the religious community and took its vows.','nun 指已加入宗教团体的女性成员，立誓是此处定义中的关键信息。','meaning'),[q('What did the nun tend?','the community garden','a nuclear reactor','a fraction numerator','她照料社区花园。'),q('Which woman is a nun?','a woman who belongs to a religious community under vows','a visitor who attends one public lecture','a nurse who has never joined a religious community','nun 指立誓加入宗教团体的女性。',1,'meaning'),q('What did she teach the children to identify?','herbs used in the kitchen','Roman numerals on a doorway','dangerous gases in the greenhouse','她教孩子们辨认厨房使用的香草。',1,'context'),q('Which word is the historical source named for nun?','Latin nonna','Latin numerus','Old French nuire','nun 的词源与拉丁语 nonna 有关。',1,'word-formation')]);
P('nurse','Nurse comes through Middle English from Latin nutricia, “a female caretaker”; it can name a caregiver, mean to care for someone, or mean feed a baby or sustain a feeling.',[C('nurse.s1','护士','A nurse checked the patient’s temperature and recorded the result before the doctor arrived.','医生到达前，护士测量了病人的体温并记录结果。','A nurse checked the patient’s temperature / and recorded the result / before the doctor arrived.','nurse 作名词指受过训练、照护病患或伤者的人。','测体温和记录属于护理工作。'),C('nurse.s2','护理；照料','After surgery, her family took turns nursing her at home until she could walk without help.','手术后，家人轮流在家照料她，直到她能独立行走。','After surgery / her family took turns nursing her at home / until she could walk without help.','nurse 作动词可指照顾生病或无法自理的人。','家人持续照料她直到康复。'),C('nurse.s3','喂奶；怀有','The mother nursed her newborn, while the coach nursed a hope that the injured team would recover before the final.','母亲给新生儿喂奶，教练则怀着受伤队员能在决赛前恢复的希望。','The mother nursed her newborn / while the coach nursed a hope / that the injured team would recover before the final.','nurse 还可指给婴儿喂奶，或持续怀有某种感情、希望。','同一句展示喂养和心怀希望两个用法。')],M('The nurse ignored the patient’s temperature and refused to record any change before the doctor arrived.','The nurse checked the patient’s temperature and recorded the result before the doctor arrived.','护士的例句职责是测量并记录体温，忽略检查不能满足该任务。','meaning'),[q('What did the nurse measure?','the patient’s temperature','the fraction’s numerator','the nursery’s floor area','护士测量病人体温。'),q('What did her family do after surgery?','nursed her at home','numbered her medical notes','opened a new nursery','家人轮流照料她直到她能独立行走。',2,'context'),q('What did the mother do for her newborn?','nursed the baby','nursed a legal nuisance','nursed a river gauge','nurse 在此表示给婴儿喂奶。',3,'meaning'),q('Which use of nurse is figurative?','The coach nursed a hope that the team would recover.','The nurse checked the patient’s pulse.','The mother nursed her newborn.','心怀希望是 nurse 的比喻用法。',3,'distinction')]);
P('nursery','Nursery combines nurse with -ery and can mean a place for young children, a place where plants are raised, or a room for a baby.',[C('nursery.s1','托儿所；幼儿园','The council opened a nursery near the station so parents could leave young children there during work hours.','市政部门在车站附近开办了托儿所，让家长可以在工作时间把幼儿托付在那里。','The council opened a nursery near the station / so parents could leave young children there / during work hours.','nursery 可指白天照看幼儿的场所。','家长工作时把孩子交由托儿所照看。'),C('nursery.s2','苗圃；育苗场','The plant nursery supplied native trees for the restoration project along the riverbank.','苗圃为河岸修复工程提供了本地树种。','The plant nursery supplied native trees / for the restoration project / along the riverbank.','plant nursery 指培育并出售植物或树苗的苗圃。','苗圃为修复项目提供树木。'),C('nursery.s3','婴儿室','Before the baby came home, the family painted the nursery and assembled a small cot beside the window.','宝宝回家前，家人粉刷了婴儿室，并在窗边组装了一张小婴儿床。','Before the baby came home / the family painted the nursery / and assembled a small cot beside the window.','nursery 也可指家中供婴儿使用的房间。','婴儿床和迎接宝宝说明是家中的婴儿室。')],M('The plant nursery cared for seedlings by keeping every young tree in a childcare classroom for toddlers.','The plant nursery cared for seedlings in a place where young plants were grown.','植物苗圃培育植物，不是照看幼儿的托儿所。','distinction'),[q('Where did parents leave their young children during work?','at the nursery near the station','at the plant nursery along the river','in the family’s baby room','第一种 nursery 是日间照看幼儿的场所。'),q('What did the plant nursery supply?','native trees','a cot for the baby','a nurse’s uniform','苗圃为河岸修复提供本地树木。',2,'context'),q('Where did the family assemble a cot?','in the nursery at home','in a plant nursery','in a train station nursery','cot 表明 nursery 指家中婴儿室。',3,'meaning'),q('Which nursery grows plants for sale or transplanting?','a plant nursery','a childcare nursery','a baby’s bedroom','苗圃用来培育植物。',2,'distinction')]);
P('nursing','Nursing is the -ing form of nurse; as a noun it means the profession of caring for the ill, or feeding and caring for a baby or young animal.',[C('nursing.s1','护理职业','Nursing requires careful observation because a small change in a patient’s breathing can matter.','护理工作需要细致观察，因为病人呼吸的一点变化都可能很重要。','Nursing requires careful observation / because a small change in a patient’s breathing / can matter.','nursing 可指照料病患的职业或工作。','观察呼吸变化是护理中的重要职责。'),C('nursing.s2','哺育；喂养','The wildlife center monitored the seal’s nursing of its pup before releasing the family back to the coast.','野生动物中心监测海豹哺育幼崽的情况，然后将母子放归海岸。','The wildlife center monitored the seal’s nursing of its pup / before releasing the family / back to the coast.','nursing 也可指母亲或动物给幼儿喂养并照料。','监测的是海豹对幼崽的哺育。')],M('The wildlife center monitored the seal’s nursing of its pup, but the adult provided no milk or care.','The wildlife center monitored the seal’s nursing of its pup and checked that the young animal was being fed.','没有喂养或照料就不能称为对幼崽的 nursing。','meaning'),[q('What does nursing require in the hospital example?','careful observation of patients','growing native trees','counting concert numbers','护理工作需要仔细观察病人状况。'),q('What did the wildlife center monitor?','a seal feeding and caring for its pup','a nurse checking a patient’s temperature','a plant nursery selling trees','这里 nursing 指海豹哺育幼崽。',2,'context'),q('Which activity belongs to professional nursing?','checking a patient’s breathing and recording changes','selling seedlings at a plant nursery','writing the numerator of a fraction','护理人员需要观察并记录病人变化。',1,'meaning'),q('Nursing a pup means?','feeding and caring for the young animal','placing it in a plant nursery','counting how many seals exist','此处 nursing 表示喂养并照料幼崽。',2,'meaning')]);
P('nurture','Nurture comes through Old French from Latin nutrire, “to feed or foster”; it can mean care during growth, help a skill or feeling develop, or upbringing.',[C('nurture.s1','养育；培育','The volunteers nurtured the injured fox until it was strong enough to return to the woodland.','志愿者照料受伤的狐狸，直到它强壮到可以回到林地。','The volunteers nurtured the injured fox / until it was strong enough / to return to the woodland.','nurture 作动词可指在成长过程中照料儿童或生物。','狐狸得到持续照料直到康复。'),C('nurture.s2','培养才能或计划','The science club nurtured Maya’s interest in astronomy by letting her lead the telescope observations.','科学社团让玛雅带领望远镜观测，从而培养了她对天文学的兴趣。','The science club nurtured Maya’s interest in astronomy / by letting her lead / the telescope observations.','nurture 也可指帮助计划、技能或兴趣发展。','承担观测工作让兴趣得以成长。'),C('nurture.s3','后天养育','The study examined how nurture and family support influenced children’s language development.','研究考察了后天养育和家庭支持如何影响儿童的语言发展。','The study examined / how nurture and family support / influenced children’s language development.','nurture 作名词可指养育、照料和成长环境。','研究将成长环境与语言发展联系起来。')],M('The volunteers nurtured the injured fox by abandoning it without food or medical care.','The volunteers nurtured the injured fox by feeding it and helping it recover.','弃养且不给食物或照料不是 nurture。','meaning'),[q('What happened to the injured fox?','volunteers cared for it until it recovered','it was left without food in the woodland','it was placed in a nursery classroom','志愿者照料狐狸直到它能够回到林地。'),q('How did the science club nurture Maya’s interest?','it let her lead telescope observations','it prevented her from using the telescope','it enrolled her in a nursery','社团给她观测机会，帮助兴趣发展。',2,'context'),q('In the research study, what did nurture refer to?','upbringing and family support','the fox’s return route only','the number of telescopes','nurture 作名词指养育和成长环境。',3,'meaning'),q('Which example uses nurture to mean develop a skill or interest?','A mentor nurtured her talent for mathematics.','A parent nurtured a sick child back to health.','The report compared nurture with nature.','导师帮助数学才能发展，是培养技能的用法。',2,'distinction')]);
P('nut','Nut comes from Old English hnutu; it can mean a hard-shelled edible seed, a metal fastener, or informally a person who is eccentric or very enthusiastic.',[C('nut.s1','坚果','The recipe calls for toasted hazelnuts, but the cook checks first that none of the guests has a nut allergy.','食谱需要烤榛子，但厨师先确认没有客人对坚果过敏。','The recipe calls for toasted hazelnuts / but the cook checks first / that none of the guests has a nut allergy.','nut 可指带硬壳、可食用的干果种子。','榛子属于坚果，需考虑过敏风险。'),C('nut.s2','螺母；螺帽','She tightened the nut onto the bolt to secure the wheel before testing the cart.','测试推车前，她把螺母拧到螺栓上固定车轮。','She tightened the nut onto the bolt / to secure the wheel / before testing the cart.','nut 也可指拧在螺栓上的金属螺母。','螺母与螺栓配合固定车轮。'),C('nut.s3','狂热者；怪人（口语）','My uncle is a jazz nut who travels across the country to hear small bands play.','我叔叔是个爵士乐迷，常常跨越整个国家去听小乐队演出。','My uncle is a jazz nut / who travels across the country / to hear small bands play.','口语中 nut 可指对某事极其热衷的人，也可能指古怪的人。','jazz nut 是对爵士乐极其热衷的人。')],M('She secured the cart wheel by tightening a hazelnut onto the metal bolt.','She secured the cart wheel by tightening a metal nut onto the bolt.','食用榛子不能拧在螺栓上固定车轮。','distinction'),[q('What ingredient did the recipe call for?','toasted hazelnuts','a metal bolt','a jazz record','食谱需要烤榛子。'),q('What did she tighten onto the bolt?','a metal nut','a hazelnut','a wheel bearing made of paper','金属螺母与螺栓固定车轮。',2,'context'),q('What does “a jazz nut” mean informally?','a person very enthusiastic about jazz','a metal fastener shaped like a music note','a person allergic to all nuts','jazz nut 指爵士乐狂热爱好者。',3,'meaning'),q('Which item is an edible nut?','a hazelnut','a steel fastener','a bolt threaded through a wheel','榛子是可食用坚果。',1,'distinction')]);
P('nutmeg','Nutmeg combines nut with a word borrowed through French from muscade; it names the aromatic seed grated into food or drink.',C('nutmeg.s1','肉豆蔻','The baker grated a little nutmeg into the warm custard to add a sweet, woody aroma.','烘焙师在温热的蛋奶酱里磨入少许肉豆蔻，增添甜润的木质香气。','The baker grated a little nutmeg / into the warm custard / to add a sweet, woody aroma.','nutmeg 指常磨碎后用于食品或饮料的芳香种子。','磨入蛋奶酱的是香料肉豆蔻。'),M('The baker grated nutmeg into the custard to make it taste completely odorless and flavorless.','The baker grated nutmeg into the custard to give it a warm, aromatic flavor.','肉豆蔻用于增添香味，不是让食物失去味道。','meaning'),[q('What did the baker grate into the custard?','nutmeg','a steel nut','a Roman numeral','烘焙师磨入了肉豆蔻。'),q('How is nutmeg commonly used in food?','grated as an aromatic spice','tightened onto a bolt','written as a fraction','肉豆蔻常磨碎后作为芳香香料。',1,'meaning'),q('What quality did it add to the custard?','a sweet, woody aroma','a metallic fastening','a sour river taste','肉豆蔻增添甜润的木质香气。',1,'context'),q('Which word part names the nut-like seed?','nut','-ify','nurse','nutmeg 的复合词首部是 nut。',1,'word-formation')]);
P('nutrient','Nutrient is formed from Latin nutrire, “to nourish,” with -ent; it means a substance living things need to grow and stay healthy.',C('nutrient.s1','营养物；养分','The soil test showed that the young trees needed more nitrogen, an important nutrient for healthy leaf growth.','土壤检测显示，幼树需要更多氮；氮是叶片健康生长的重要养分。','The soil test showed / that the young trees needed more nitrogen / an important nutrient for healthy leaf growth.','nutrient 指生物生长和保持健康所需的物质。','氮是帮助叶片生长的养分。'),M('The soil lacked the nutrient nitrogen, so the trees grew vigorously without any growth-supporting substance.','The soil lacked the nutrient nitrogen, so the trees showed poor leaf growth.','缺少必要养分会影响生长，不会让植物在没有养分时旺盛生长。','meaning'),[q('Which nutrient did the young trees need more of?','nitrogen','nutmeg','nuclear energy','土壤检测发现幼树需要更多氮。'),q('What is a nutrient?','a substance living things need for growth and health','a metal part screwed onto a bolt','a person who writes novels','养分是生物生长和保持健康所需的物质。',1,'meaning'),q('What growth does nitrogen support in the example?','healthy leaf growth','the growth of a music program','the growth of a paper notebook','氮有助于叶片健康生长。',1,'context'),q('Which verb is related to nutrient’s historical root?','nourish','nudge','number','nutrient 的词源与“滋养”有关。',1,'word-formation')]);
P('nutriment','Nutriment comes from Latin nutrimentum, from nutrire, “to nourish”; it means food that sustains the body or, figuratively, something that feeds the mind.',[C('nutriment.s1','营养物；养料','The field mice found enough nutriment in the seed store to survive the cold weeks.','田鼠在种子储藏处找到了足够的食物，得以熬过寒冷的几周。','The field mice found enough nutriment / in the seed store / to survive the cold weeks.','nutriment 可指维持身体健康和生长的食物或营养。','种子为田鼠提供过冬所需食物。'),C('nutriment.s2','精神食粮','The historian called the old letters nutriment for her imagination because they revealed daily life in the port.','历史学家称这些旧信件是她想象力的精神食粮，因为它们揭示了港口的日常生活。','The historian called the old letters nutriment for her imagination / because they revealed / daily life in the port.','nutriment 也可比喻指滋养思想或精神的东西。','信件为历史研究和想象提供了材料。')],M('The mice survived the winter on nutriment even though they found no food, seed, or other sustenance.','The mice survived the winter on nutriment from the stored seeds.','没有任何食物或补给就不能说靠 nutriment 生存。','meaning'),[q('What helped the field mice survive the cold weeks?','seeds in the store','old letters from the port','a number written on the door','储藏的种子给田鼠提供食物。'),q('What was nutriment for the historian’s imagination?','the old letters','the field mice','the seed store’s temperature','旧信件为历史学家的想象提供精神材料。',2,'context'),q('Which is physical nutriment?','food that supplies energy and nutrients','a letter that informs a historian','a novel with no food in it','食物为身体提供能量和营养。',1,'meaning'),q('Which use of nutriment is figurative?','A challenging book was nutriment for her thinking.','The seeds were nutriment for the mice.','The nurse recorded a temperature.','书籍滋养思想是比喻用法。',2,'distinction')]);
P('nutrition','Nutrition comes from Latin nutritionem, from nutrire, “to nourish”; it can mean the process of taking in food or the scientific study of food and health.',[C('nutrition.s1','营养；滋养过程','Good nutrition helped the recovering patient regain strength through a balanced diet and regular meals.','均衡饮食和规律进餐带来良好营养，帮助康复中的病人恢复体力。','Good nutrition helped the recovering patient regain strength / through a balanced diet / and regular meals.','nutrition 可指生物摄取和利用食物以维持健康的过程。','均衡饮食为康复提供所需营养。'),C('nutrition.s2','营养学','She studied nutrition at university and now researches how school meals affect children’s concentration.','她在大学学习营养学，现在研究学校餐食如何影响儿童的注意力。','She studied nutrition at university / and now researches / how school meals affect children’s concentration.','nutrition 也指研究食物及其对身体影响的科学领域。','大学课程和研究表明 nutrition 是学科名称。')],M('She studied nutrition at university but never learned anything about food or its effects on the body.','She studied nutrition at university to learn how food affects health.','营养学研究食物及其对身体的影响。','meaning'),[q('How did the patient regain strength?','through balanced nutrition and regular meals','by using a metal nut','by avoiding all food','均衡饮食和规律进餐改善营养。'),q('What does the researcher study?','how school meals affect children’s concentration','how to label raffle tickets','how to repair a river nozzle','她研究学校餐食对儿童注意力的影响。',2,'context'),q('Which use means the scientific field?','She earned a degree in nutrition.','The patient needs better nutrition.','The seedlings received nutriment.','获得学位说明 nutrition 指营养学。',2,'meaning'),q('Which use refers to food intake supporting health?','Good nutrition supports recovery.','Nutrition is taught as a university subject.','She studied a nutrition textbook.','第一句中的 nutrition 指营养过程。',1,'meaning')]);
P('nutritional','Nutritional combines nutrition with -al and means connected with nutrition or the value of food.',C('nutritional.s1','营养的；营养方面的','The label lists the nutritional content of each serving so shoppers can compare protein and fiber.','标签列出每份食品的营养成分，方便消费者比较蛋白质和纤维。','The label lists the nutritional content / of each serving / so shoppers can compare protein and fiber.','nutritional 作形容词，表示与营养或食品价值有关。','成分表提供营养方面的信息。'),M('The label gives nutritional information but lists no nutrients, food values, or serving details.','The label gives nutritional information by listing the nutrients in each serving.','没有营养素或相关信息就不能称为 nutritional information。','meaning'),[q('What information does the label list?','nutrients in each serving','the nurse’s work schedule','the number of concert pieces','标签列出每份的营养成分。'),q('Which phrase uses nutritional correctly?','nutritional value of the meal','nutritional nurse who tends a patient','nutritional number that marks a door','nutritional 修饰与食物营养相关的 value。',1,'word-formation'),q('Why can shoppers compare the products?','the label shows protein and fiber','the label hides every ingredient','the label lists only the store address','营养信息让消费者比较蛋白质和纤维。',1,'context'),q('What does -al contribute in nutritional?','an adjective meaning related to nutrition','a person who studies fractions','the plural of nutrient','-al 构成“营养相关的”形容词。',1,'word-formation')]);
P('nutritionally','Nutritionally is formed from nutritional plus -ly and means in terms of nutritional value.',C('nutritionally.s1','营养上','The two lunch options are nutritionally similar, although one contains beans and the other contains lentils.','两种午餐在营养上相近，尽管一种含豆类，另一种含扁豆。','The two lunch options are nutritionally similar / although one contains beans / and the other contains lentils.','nutritionally 是副词，表示从营养价值的角度看。','比较的是两种餐食的营养组成。'),M('The lunches were nutritionally identical because one supplied protein and fiber while the other contained no nutrients at all.','The lunches were nutritionally different because only one supplied protein and fiber.','营养成分完全不同，不能说在营养上完全相同。','meaning'),[q('How do the two lunch options compare?','they are similar in nutritional value','one is a nursery and one is a nut','they have exactly the same ingredients','句子说两种午餐营养相近。'),q('Which comparison is nutritionally focused?','comparing protein and fiber in two meals','comparing the plates’ colors only','comparing how quickly diners walk','nutritionally 表示从营养方面进行比较。',1,'meaning'),q('What is different between the meals?','one contains beans and the other lentils','one is served in November and one in June','one contains no food','两种午餐食材不同，但营养相近。',1,'context'),q('Which form is the base adjective of nutritionally?','nutritional','nourishment','numerical','nutritionally 由形容词 nutritional 加 -ly 构成。',1,'word-formation')]);
P('nutritionist','Nutritionist combines nutrition with -ist and names a specialist who studies nutrients or plans diets.',C('nutritionist.s1','营养学家；营养师','The nutritionist designed a meal plan with enough iron for the runner’s training schedule.','营养师根据跑步者的训练安排设计了一份含铁量充足的膳食计划。','The nutritionist designed a meal plan / with enough iron / for the runner’s training schedule.','nutritionist 指研究营养或规划饮食的专业人员。','膳食计划针对训练需求和铁摄入。'),M('The nutritionist designed the meal plan without considering food, nutrients, or the runner’s health.','The nutritionist designed a meal plan that considered the runner’s nutrient needs.','营养师的工作会考虑食物与营养需求。','meaning'),[q('What did the nutritionist design?','a meal plan with enough iron','a Roman numeral for the doorway','a nut for a bolt','营养师设计了含铁量充足的膳食计划。'),q('Who is a nutritionist?','a specialist in food and nutrients','a person who numbers tickets','a member of a religious community under vows','nutritionist 是研究营养或规划饮食的专业人员。',1,'meaning'),q('Whose needs shaped the meal plan?','the runner’s training needs','the museum’s visitors','the plant nursery’s sales plan','计划根据跑步者的训练安排制定。',1,'context'),q('What does -ist commonly name in nutritionist?','a person associated with a field or activity','a state of being new','a quality relating to number','-ist 常用于构成领域相关的从业者名称。',1,'word-formation')]);
})();
